INSERT INTO public.topics (id, title, slug, usmle_step, "order", section, is_free_demo, mcq_count, case_count)
INSERT INTO public.mcqs (topic_id, question, options, correct_index, explanation, difficulty, "order", type) VALUES
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 68-year-old man with a 40 pack-year smoking history presents with progressive dyspnea on exertion and a chronic productive cough for the past 3 years. Examination shows a barrel-shaped chest, hyperresonance to percussion, and a prolonged expiratory phase with diffuse wheezing. Spirometry reveals an FEV1/FVC ratio of 0.62 and an FEV1 of 55% of predicted. Which of the following is the most likely diagnosis?', '["Asthma", "Chronic obstructive pulmonary disease", "Idiopathic pulmonary fibrosis", "Bronchiectasis", "Congestive heart failure"]'::jsonb, 1, 'A post-bronchodilator FEV1/FVC ratio below 0.70 defines persistent airflow limitation, the hallmark of COPD, and an FEV1 of 55% of predicted places him in GOLD grade 2 (moderate). His 40 pack-year history, chronic productive cough, barrel chest, and hyperresonance all fit COPD. Asthma typically shows reversible airflow obstruction with a large bronchodilator response and often begins earlier with atopy. Idiopathic pulmonary fibrosis causes restriction, not obstruction, with low DLCO and basal crackles. Bronchiectasis produces large volumes of purulent sputum and dilated airways on CT. Heart failure causes orthopnea, edema, and elevated jugular venous pressure rather than obstructive spirometry.', 'Medium', 1, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 72-year-old woman with a 30 pack-year smoking history has chronic cough and progressive dyspnea. Post-bronchodilator spirometry shows an FEV1/FVC ratio of 0.58, and her FEV1 improves by only 80 mL (6%) after inhaled albuterol. She has no history of atopy. Which of the following findings best supports a diagnosis of COPD rather than asthma?', '["Elevated serum IgE level", "Peripheral blood eosinophilia", "Positive methacholine challenge test", "Persistent airflow limitation with minimal bronchodilator reversibility", "Predominantly nocturnal cough"]'::jsonb, 3, 'COPD is defined by persistent airflow limitation (post-bronchodilator FEV1/FVC below 0.70) with only partial, small bronchodilator reversibility; here the improvement is 6%, below the 12% and 200 mL threshold for significant reversibility. The absolute change of only 80 mL also falls short of the 200 mL component of the threshold, further confirming fixed obstruction rather than reversible airway disease. Asthma, by contrast, shows large reversible increases in FEV1. Elevated IgE and peripheral eosinophilia suggest atopy and asthma, not COPD. A positive methacholine challenge demonstrates airway hyperresponsiveness and supports asthma. Predominantly nocturnal cough is typical of asthma and is not discriminating.', 'Hard', 2, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 65-year-old man with a 50 pack-year smoking history has progressive dyspnea. Spirometry shows an FEV1 of 32% of predicted with an FEV1/FVC ratio of 0.55. His modified Medical Research Council dyspnea grade is 3, and he has had two exacerbations in the past year requiring systemic corticosteroids. What is his GOLD spirometric grade?', '["GOLD 1 (mild)", "GOLD 2 (moderate)", "GOLD 3 (severe)", "GOLD 4 (very severe)", "Cannot be graded without DLCO measurement"]'::jsonb, 2, 'GOLD spirometric grading uses FEV1 as a percentage of predicted: GOLD 1 is 80% or higher, GOLD 2 is 50 to 79%, GOLD 3 is 30 to 49%, and GOLD 4 is below 30%. An FEV1 of 32% of predicted is therefore GOLD 3 (severe). His exacerbation history and mMRC grade determine the GOLD A, B, or E grouping, not the numeric grade. DLCO is not needed to assign the GOLD grade. GOLD 4 requires an FEV1 below 30% of predicted, which he has not reached.', 'Easy', 3, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 66-year-old man with COPD (GOLD grade 2, modified Medical Research Council dyspnea grade 2) has had no exacerbations in the past year and currently uses only as-needed albuterol. He remains short of breath when walking one block. What is the most appropriate next step in his chronic management?', '["Start a daily long-acting muscarinic antagonist (LAMA)", "Start an inhaled corticosteroid alone", "Start daily oral prednisone", "Start theophylline", "Start long-term oxygen therapy"]'::jsonb, 0, 'This patient is in GOLD group B (mMRC grade 2, no exacerbations) and is using only a short-acting bronchodilator. GOLD recommends a long-acting bronchodilator, a LAMA (or LABA), as maintenance therapy for symptomatic patients. An inhaled corticosteroid alone is not recommended in COPD and increases pneumonia risk. Daily oral prednisone has no role in stable COPD. Theophylline is a weak bronchodilator with a narrow therapeutic window and is not first-line. Long-term oxygen is indicated only for severe resting hypoxemia (PaO2 55 mmHg or lower, or SpO2 88% or lower).', 'Medium', 4, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 70-year-old man with COPD has had two exacerbations in the past year despite adherence to a LABA plus LAMA inhaler. His blood eosinophil count is 350 cells per microliter. He continues to have dyspnea on minimal exertion. What is the most appropriate next step in management?', '["Switch to a LABA alone", "Add roflumilast", "Add daily azithromycin", "Add daily oral prednisone", "Add an inhaled corticosteroid (triple therapy)"]'::jsonb, 4, 'In a frequent exacerbator already on LABA plus LAMA with blood eosinophils of 300 cells per microliter or higher, GOLD recommends adding an inhaled corticosteroid to form triple therapy, because eosinophilic inflammation predicts responsiveness to ICS. Switching to a LABA alone would remove the LAMA and worsen control. Roflumilast is reserved for the chronic bronchitis phenotype with severe obstruction despite triple therapy. Daily azithromycin is an option for frequent exacerbators but is considered after ICS in eosinophilic patients. Chronic oral prednisone is not used in stable COPD.', 'Hard', 5, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 64-year-old woman with COPD and a chronic bronchitis phenotype has an FEV1 of 45% of predicted. She is adherent to LABA plus LAMA plus inhaled corticosteroid therapy and has quit smoking, yet she continues to have exacerbations. What is the most appropriate next step in management?', '["Increase the inhaled corticosteroid dose", "Add daily azithromycin", "Start daily oral prednisone", "Refer for lung transplantation", "Add theophylline"]'::jsonb, 1, 'For patients with the chronic bronchitis phenotype and severe airflow limitation who continue to exacerbate despite triple therapy, daily azithromycin reduces exacerbation frequency. Long-term macrolide therapy is particularly effective in the chronic bronchitis phenotype and also reduces airway inflammation. Before starting it, clinicians should check an ECG for QT prolongation, assess hearing, and screen sputum for nontuberculous mycobacteria. Increasing the inhaled corticosteroid dose does not further reduce exacerbations and raises pneumonia risk. Chronic oral prednisone is not recommended in stable COPD. Lung transplantation is reserved for very severe disease with refractory hypoxemia and is not the next step here. Theophylline is a weak bronchodilator with significant toxicity and is not preferred.', 'Medium', 6, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 71-year-old man with COPD presents with 3 days of worsening dyspnea and increased purulent sputum. His respiratory rate is 28 per minute, oxygen saturation is 88% on room air, and arterial blood gas shows pH 7.32, PaCO2 58 mmHg, and bicarbonate 30 mEq/L. He is alert and able to cooperate. What is the most appropriate next step in management?', '["Immediate endotracheal intubation", "High-flow nasal cannula alone", "Noninvasive ventilation (BiPAP)", "Intravenous methylprednisolone alone", "Nebulized ipratropium alone"]'::jsonb, 2, 'An acute COPD exacerbation with acute-on-chronic hypercapnic respiratory failure (pH 7.32, PaCO2 58 mmHg) is the classic indication for noninvasive ventilation (BiPAP), which reduces the need for intubation and lowers mortality. Bilevel pressure support unloads the respiratory muscles and improves alveolar ventilation while avoiding the complications of an endotracheal tube, and it should be started early before severe acidosis develops. Immediate intubation is reserved for failure of noninvasive ventilation, apnea, or inability to protect the airway. High-flow nasal cannula does not provide the ventilatory support needed for hypercapnia. Intravenous steroids alone do not correct ventilatory failure. Nebulized ipratropium is adjunctive bronchodilator therapy, not treatment for respiratory failure.', 'Medium', 7, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 69-year-old man with COPD presents with increased dyspnea, increased sputum volume, and increased sputum purulence over 2 days. He is afebrile, and chest radiography shows no infiltrate. What is the most appropriate management?', '["Systemic corticosteroids plus an antibiotic", "Systemic corticosteroids only, without antibiotics", "Intravenous vancomycin", "Oseltamivir", "Inhaled tobramycin"]'::jsonb, 0, 'All three Anthonisen criteria are present (increased dyspnea, sputum volume, and purulence), so antibiotics are indicated alongside systemic corticosteroids, which shorten recovery and reduce treatment failure. Typical antibiotic choices include a macrolide, doxycycline, or amoxicillin-clavulanate, depending on local resistance and prior cultures. Corticosteroids shorten the recovery time and reduce the risk of treatment failure, while antibiotics are most beneficial when sputum purulence is present. Corticosteroids alone are insufficient when bacterial infection is suggested by purulent sputum. Intravenous vancomycin is unnecessarily broad for a community-acquired exacerbation without MRSA risk factors. Oseltamivir treats influenza, not a bacterial exacerbation. Inhaled tobramycin is used for chronic Pseudomonas colonization in bronchiectasis or cystic fibrosis, not for an acute COPD exacerbation.', 'Medium', 8, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 62-year-old man admitted for a COPD exacerbation was started on prednisone 40 mg daily and is improving. He has no history of diabetes or psychiatric disease. What is the recommended duration of systemic corticosteroid therapy for his exacerbation?', '["3 days", "10 days", "14 days", "5 days", "Continue until the FEV1 normalizes"]'::jsonb, 3, 'GOLD recommends a 5-day course of prednisone 40 mg daily for COPD exacerbations; longer courses increase adverse effects without added benefit. This recommendation comes from trials comparing 5-day and 14-day courses, which showed no difference in treatment failure or time to the next exacerbation. A 3-day course is shorter than the evidence-based duration. Ten- and 14-day courses were used historically, but trials show 5 days is non-inferior. Shorter courses reduce the risk of hyperglycemia, insomnia, weight gain, and adrenal suppression, which is particularly important in older patients with comorbid diabetes or osteoporosis. Continuing steroids until the FEV1 normalizes is not recommended and exposes the patient to hyperglycemia, infection, and other harms.', 'Easy', 9, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 24-year-old woman with asthma reports daytime symptoms 3 days per week, nighttime awakenings twice a month, and albuterol use 3 times per week. Her FEV1 is 85% of predicted. She has no daily symptoms and no activity limitation. How should her asthma severity be classified?', '["Intermittent asthma", "Moderate persistent asthma", "Severe persistent asthma", "Cannot be classified without FeNO measurement", "Mild persistent asthma"]'::jsonb, 4, 'Mild persistent asthma is defined by symptoms more than 2 days per week but not daily, nighttime awakenings 3 to 4 times per month, and an FEV1 of 80% of predicted or higher, all of which are present here. Intermittent asthma has symptoms 2 days per week or less and nighttime awakenings 2 times per month or less. Moderate persistent asthma has daily symptoms and an FEV1 of 60 to 80%. Severe persistent asthma has symptoms throughout the day and an FEV1 below 60%. FeNO measurement is not required to classify asthma severity.', 'Easy', 10, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 32-year-old woman with mild persistent asthma is taking a low-dose inhaled corticosteroid daily but still has symptoms 3 days per week and uses albuterol 3 times per week. She has no history of intubation. What is the most appropriate next step in her controller therapy?', '["Add daily oral prednisone", "Step up to low-dose ICS-formoterol as maintenance and reliever therapy (MART)", "Stop the inhaled corticosteroid and use a short-acting beta-agonist only", "Add omalizumab", "Add theophylline"]'::jsonb, 1, 'For mild persistent asthma that remains uncontrolled on a low-dose inhaled corticosteroid, GINA recommends stepping up to low-dose ICS-formoterol as maintenance and reliever therapy (MART), which reduces severe exacerbations, or adding a long-acting beta-agonist. MART uses the same ICS-formoterol inhaler for daily maintenance and as-needed relief, providing anti-inflammatory treatment with every reliever dose. This strategy has been shown to reduce severe exacerbations compared with short-acting beta-agonist-only reliever use. Daily oral prednisone is not used for maintenance because of severe long-term toxicity. Stopping the inhaled corticosteroid and using a short-acting beta-agonist alone leaves airway inflammation untreated. Omalizumab is reserved for severe allergic asthma uncontrolled on high-dose ICS-LABA. Theophylline is not a preferred add-on therapy.', 'Medium', 11, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 28-year-old man with moderate persistent asthma is taking a low-dose ICS-LABA inhaler daily but has poor control with frequent short-acting beta-agonist use and nighttime awakenings. He uses correct inhaler technique and is adherent. What is the most appropriate next step in management?', '["Add daily oral corticosteroids", "Stop the inhaled corticosteroid and switch to a LABA alone", "Increase to a medium-dose ICS-LABA inhaler", "Add theophylline", "Add daily ipratropium"]'::jsonb, 2, 'When moderate persistent asthma is uncontrolled on a low-dose ICS-LABA inhaler, the next step is to increase to a medium-dose ICS-LABA combination before considering biologic therapy. If control remains poor on medium-dose ICS-LABA, the next steps include rechecking adherence and inhaler technique, assessing for triggers, and considering add-on therapy such as a LAMA or a biologic agent targeted to the patient''s phenotype. Daily oral corticosteroids are not used for maintenance because of severe long-term toxicity. LABA monotherapy without an inhaled corticosteroid is contraindicated in asthma because it increases the risk of severe exacerbations and death. Theophylline is a weak add-on with a narrow therapeutic index. Daily ipratropium is not a standard controller medication in asthma.', 'Medium', 12, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 19-year-old woman with asthma presents with acute shortness of breath. Her respiratory rate is 32 per minute, heart rate 128 per minute, oxygen saturation 89% on room air, and peak expiratory flow is 40% of predicted. She uses accessory muscles and cannot speak in full sentences. What is the most appropriate initial management?', '["Continuous nebulized albuterol plus ipratropium and systemic corticosteroids", "Oral theophylline", "Inhaled corticosteroid alone", "Intravenous magnesium sulfate only", "Discharge home with an albuterol inhaler"]'::jsonb, 0, 'A severe asthma exacerbation (peak expiratory flow 40% of predicted, accessory muscle use, inability to speak in full sentences, oxygen saturation 89%) requires continuous nebulized short-acting beta-agonist plus ipratropium and early systemic corticosteroids, with oxygen to maintain saturation at 93 to 95%. Oral theophylline is not first-line and has significant toxicity. An inhaled corticosteroid alone acts too slowly for an acute severe exacerbation. Intravenous magnesium is an adjunct for severe exacerbations not responding to initial therapy, not the initial step. Discharging this patient would be unsafe.', 'Medium', 13, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 26-year-old man with a severe asthma exacerbation has received continuous nebulized albuterol, ipratropium, and intravenous methylprednisolone but continues to deteriorate. His chest is silent on auscultation, arterial blood gas shows PaCO2 55 mmHg and pH 7.28, and he is becoming drowsy. What is the most appropriate next step in management?', '["Add inhaled cromolyn", "Give intravenous theophylline", "Discharge him home", "Endotracheal intubation with controlled hypoventilation (permissive hypercapnia)", "Add oral montelukast"]'::jsonb, 3, 'This is status asthmaticus with impending respiratory failure: a silent chest, rising PaCO2, acidosis, and altered mental status. He needs endotracheal intubation with controlled hypoventilation and permissive hypercapnia, using low tidal volumes, a low respiratory rate, and prolonged exhalation to avoid air trapping and barotrauma. Cromolyn and montelukast have no role in acute management. Intravenous theophylline is not first-line and adds toxicity. Discharge would be fatal. Magnesium sulfate is an adjunct, not definitive airway management in a patient with altered mental status.', 'Hard', 14, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 22-year-old woman with an asthma exacerbation has received three nebulized albuterol-ipratropium treatments and intravenous corticosteroids, with minimal improvement after 1 hour. Her peak expiratory flow remains 45% of predicted. She is alert and speaking in short phrases. What is the most appropriate next step in management?', '["Discharge home with oral prednisone", "Add an inhaled corticosteroid only", "Add theophylline", "Give intravenous antibiotics", "Administer intravenous magnesium sulfate"]'::jsonb, 4, 'Intravenous magnesium sulfate is the recommended adjunct for severe asthma exacerbations that respond poorly to initial bronchodilator and corticosteroid therapy; it relaxes bronchial smooth muscle and improves peak expiratory flow. Discharging a patient with a peak expiratory flow of 45% of predicted after minimal improvement is unsafe. Adding an inhaled corticosteroid alone acts too slowly in the acute setting. Theophylline is not preferred because of toxicity and weak effect. Antibiotics are indicated only if bacterial infection is suspected, which is not described here.', 'Medium', 15, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 58-year-old man with a 35 pack-year smoking history has chronic cough, dyspnea, and wheeze. Pulmonary function testing shows an FEV1/FVC ratio of 0.65, and his FEV1 improves by 400 mL (16%) after bronchodilator administration. He has a history of childhood asthma and atopy, and his blood eosinophil count is 400 cells per microliter. What is the most likely diagnosis?', '["COPD alone", "Asthma-COPD overlap", "Asthma alone", "Bronchiectasis", "Congestive heart failure"]'::jsonb, 1, 'Asthma-COPD overlap is diagnosed when features of both diseases coexist: fixed airflow obstruction (FEV1/FVC ratio 0.65) with significant bronchodilator reversibility (400 mL, 16%), a history of asthma and atopy, and blood eosinophilia. The overlap syndrome is important to recognize because these patients have more frequent exacerbations, worse quality of life, and faster lung function decline than those with either disease alone. COPD alone does not show this degree of reversibility or atopic features. Asthma alone does not cause fixed obstruction in a 35 pack-year smoker. Bronchiectasis causes purulent sputum and dilated airways on imaging. Heart failure causes orthopnea and edema, not obstructive physiology with eosinophilia.', 'Medium', 16, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 60-year-old woman with asthma-COPD overlap has frequent exacerbations and remains symptomatic on a LAMA inhaler alone. Her blood eosinophil count is 320 cells per microliter. What is the most appropriate next step in management?', '["Continue the LAMA alone", "Add daily oral prednisone", "Add an inhaled corticosteroid (ICS-containing regimen)", "Add roflumilast", "Start long-term oxygen therapy"]'::jsonb, 2, 'In asthma-COPD overlap, an inhaled corticosteroid is essential because the asthma component is driven by eosinophilic airway inflammation; a LAMA alone leaves this untreated, so an ICS-containing regimen (ICS-LABA or triple therapy) is indicated. Triple therapy with ICS, LABA, and LAMA is appropriate when exacerbations persist despite dual therapy. The choice of inhaler regimen should be guided by the blood eosinophil count, exacerbation history, and symptom burden, with regular reassessment of control. Continuing the LAMA alone will not control the asthma component. Daily oral prednisone is not used for maintenance therapy. Roflumilast is for the chronic bronchitis phenotype with severe COPD, not the primary therapy for overlap. Long-term oxygen is indicated only for severe resting hypoxemia.', 'Medium', 17, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 55-year-old man with a long smoking history has fixed airflow obstruction on spirometry, but also marked bronchodilator reversibility and an elevated fractional exhaled nitric oxide (FeNO) level. Which feature most favors asthma-COPD overlap over COPD alone?', '["Significant bronchodilator reversibility with eosinophilic airway inflammation", "Hyperinflation on chest radiography", "Chronic productive cough", "Reduced DLCO", "Barrel-shaped chest"]'::jsonb, 0, 'Significant bronchodilator reversibility (an increase in FEV1 of at least 12% and at least 200 mL) together with eosinophilic airway inflammation (elevated FeNO, blood eosinophils, or atopy) is the hallmark favoring asthma-COPD overlap over COPD alone, in which obstruction is largely fixed. Other features suggesting the asthma component include a history of asthma before age 40, atopy, and variable symptoms triggered by allergens or cold air. Recognizing overlap matters because it changes therapy: an ICS must be included, whereas ICS is not routinely recommended for COPD alone without eosinophilic features. Hyperinflation, chronic productive cough, reduced DLCO, and a barrel-shaped chest are all features of COPD itself and do not distinguish overlap from COPD alone.', 'Medium', 18, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 52-year-old woman has a chronic productive cough with large volumes of purulent sputum, recurrent pneumonias, and episodes of hemoptysis. Examination reveals coarse crackles over both lung bases. High-resolution CT shows dilated airways with lack of tapering, tram-track opacities, and signet ring signs. What is the most likely diagnosis?', '["COPD", "Asthma", "Pulmonary fibrosis", "Bronchiectasis", "Lung cancer"]'::jsonb, 3, 'Bronchiectasis is defined by permanently dilated airways, shown on high-resolution CT as lack of tapering, tram-track opacities, and the signet ring sign, together with chronic purulent sputum, recurrent infections, and hemoptysis. Common causes include prior severe pneumonia, cystic fibrosis, primary ciliary dyskinesia, immunodeficiency, and allergic bronchopulmonary aspergillosis, so the underlying cause should be investigated. Daily airway clearance and prompt treatment of exacerbations are the mainstays of long-term management. COPD causes obstruction without bronchial dilation on imaging. Asthma causes reversible obstruction without chronic purulent sputum. Pulmonary fibrosis causes restriction with honeycombing, not dilated airways. Lung cancer typically presents with a mass, weight loss, and hemoptysis without diffuse airway dilation.', 'Medium', 19, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 48-year-old man with bronchiectasis has frequent exacerbations, and sputum cultures repeatedly grow Pseudomonas aeruginosa. He is already performing airway clearance. What is the most appropriate long-term management?', '["Daily oral prednisone", "Inhaled corticosteroid alone", "Long-term macrolide (azithromycin) plus airway clearance", "Surgical lobectomy for all patients", "Daily inhaled tobramycin for every patient"]'::jsonb, 4, 'For bronchiectasis with chronic Pseudomonas colonization and frequent exacerbations, long-term low-dose macrolide therapy (azithromycin) reduces exacerbations, combined with airway clearance techniques such as chest physiotherapy and mucolytics. Airway clearance techniques such as chest physiotherapy, positive expiratory pressure devices, and hypertonic saline help mobilize secretions and reduce infection risk. Before starting long-term azithromycin, clinicians should check an ECG for QT prolongation, assess hearing, and screen sputum for nontuberculous mycobacteria. Daily oral prednisone is not used in bronchiectasis. An inhaled corticosteroid alone does not reduce exacerbations and increases pneumonia risk. Lobectomy is reserved for localized disease refractory to medical therapy. Inhaled tobramycin is used selectively for chronic Pseudomonas colonization but is not first-line for every patient.', 'Hard', 20, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 60-year-old woman with bronchiectasis presents with an acute exacerbation: increased sputum volume and purulence, low-grade fever, and worsening dyspnea. Sputum culture results are pending. What is the most appropriate initial management?', '["Empiric antibiotics guided by prior cultures plus airway clearance", "High-dose inhaled corticosteroids alone", "Bronchodilators only", "Immediate lobectomy", "Oral prednisone alone"]'::jsonb, 0, 'An acute bronchiectasis exacerbation is treated with empiric antibiotics chosen based on prior sputum cultures, covering previously isolated organisms such as Pseudomonas, together with intensified airway clearance; this reduces symptoms and bacterial load. Sputum should be sent for culture before starting antibiotics so therapy can be narrowed once results return. Patients with chronic Pseudomonas colonization should receive antipseudomonal coverage, and airway clearance should be intensified during the exacerbation. Hospital admission is considered if there is hypoxemia, hemoptysis, or failure to improve. High-dose inhaled corticosteroids alone do not treat bacterial infection. Bronchodilators alone are insufficient. Lobectomy is not acute management. Oral prednisone alone does not treat infection and is not indicated.', 'Medium', 21, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'An 8-year-old boy has recurrent sinopulmonary infections, steatorrhea, failure to thrive, and salty-tasting skin. His sweat chloride level is 78 mmol/L. What is the most likely diagnosis?', '["Celiac disease", "Cystic fibrosis", "Primary ciliary dyskinesia", "Primary immunodeficiency", "Asthma"]'::jsonb, 1, 'Cystic fibrosis is caused by CFTR mutations leading to thick secretions, recurrent sinopulmonary infections, pancreatic insufficiency with steatorrhea, failure to thrive, and salty sweat; a sweat chloride of 60 mmol/L or higher is diagnostic. The CFTR protein regulates chloride transport across epithelial cells; defective function produces thick, dehydrated mucus that obstructs airways and pancreatic ducts. Diagnosis is confirmed by sweat chloride testing or CFTR genetic analysis, and management is multidisciplinary, involving pulmonary, nutritional, and endocrine care. Celiac disease causes malabsorption without recurrent pulmonary infections. Primary ciliary dyskinesia causes recurrent infections but not pancreatic insufficiency or elevated sweat chloride. Immunodeficiency causes recurrent infections without steatorrhea. Asthma does not cause steatorrhea or failure to thrive.', 'Easy', 22, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 24-year-old woman with cystic fibrosis has an FEV1 of 55% of predicted, chronic Pseudomonas colonization, and frequent exacerbations. Which therapy improves lung function and reduces exacerbations in this patient?', '["Daily oral prednisone", "High-dose inhaled corticosteroid", "Inhaled dornase alfa (and/or inhaled tobramycin)", "Theophylline", "Inhaled ipratropium alone"]'::jsonb, 2, 'Inhaled dornase alfa (recombinant human DNase) thins cystic fibrosis mucus by cleaving DNA released from neutrophils, improving FEV1 and reducing exacerbations; inhaled tobramycin similarly targets chronic Pseudomonas colonization. Dornase alfa is given by nebulization once daily and is most effective when combined with regular airway clearance techniques. Inhaled tobramycin, given in alternating 28-day cycles, reduces Pseudomonas density and exacerbation frequency. CFTR modulator therapy is also available for patients with responsive mutations. Daily oral prednisone is not used in cystic fibrosis. High-dose inhaled corticosteroid does not improve cystic fibrosis outcomes. Theophylline has no role in cystic fibrosis. Inhaled ipratropium alone is not a disease-modifying therapy for cystic fibrosis.', 'Medium', 23, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 16-year-old boy with cystic fibrosis develops new hemoptysis, fever, and increased sputum production. Sputum culture grows Pseudomonas aeruginosa. What is the most likely cause of his acute deterioration?', '["Allergic bronchopulmonary aspergillosis", "Pneumothorax", "Cor pulmonale", "Acute pulmonary exacerbation due to Pseudomonas aeruginosa", "Nasal polyps"]'::jsonb, 3, 'An acute pulmonary exacerbation in cystic fibrosis (increased cough and sputum, fever, and hemoptysis) is most often due to Pseudomonas aeruginosa infection and is treated with antipseudomonal antibiotics. Treatment involves admission, airway clearance, and intravenous antipseudomonal antibiotics such as tobramycin plus a beta-lactam, guided by prior culture and susceptibility results. Early aggressive treatment is essential because each exacerbation causes a stepwise decline in lung function that may not fully recover. Allergic bronchopulmonary aspergillosis causes wheeze, eosinophilia, and elevated IgE rather than acute febrile deterioration. Pneumothorax causes sudden pleuritic pain and dyspnea with absent breath sounds. Cor pulmonale is chronic right heart failure, not an acute febrile event. Nasal polyps cause obstruction, not hemoptysis.', 'Medium', 24, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 44-year-old nonsmoking man has early-onset emphysema that is lower-lobe predominant on CT, with a history of liver disease. His serum alpha-1 antitrypsin level is markedly low. What is the most likely diagnosis?', '["COPD from cigarette smoking", "Cystic fibrosis", "Asthma", "Bronchiectasis", "Alpha-1 antitrypsin deficiency"]'::jsonb, 4, 'Early-onset panacinar emphysema with lower-lobe predominance in a nonsmoker, together with liver disease and a low serum alpha-1 antitrypsin level, is classic for alpha-1 antitrypsin deficiency (PiZZ phenotype). The PiZZ genotype produces severely reduced circulating alpha-1 antitrypsin, leaving lung elastin unprotected against neutrophil elastase and the liver burdened by misfolded protein. Family screening is recommended because first-degree relatives may be affected, and smoking dramatically accelerates lung destruction in these patients. Smoking-related COPD causes centrilobular, upper-lobe-predominant emphysema in smokers. Cystic fibrosis causes bronchiectasis and pancreatic disease, not panacinar emphysema. Asthma is reversible airflow obstruction. Bronchiectasis causes purulent sputum and dilated airways on imaging.', 'Medium', 25, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 50-year-old man with PiZZ alpha-1 antitrypsin deficiency has an FEV1 of 40% of predicted and remains symptomatic despite smoking cessation and maximal bronchodilator therapy. What is the most appropriate next step in management?', '["Weekly intravenous alpha-1 antitrypsin augmentation therapy", "Daily oral prednisone", "Lung volume reduction surgery", "Inhaled corticosteroid alone", "High-dose theophylline"]'::jsonb, 0, 'For symptomatic PiZZ patients with an FEV1 of 65% of predicted or lower despite optimal therapy and smoking cessation, weekly intravenous alpha-1 antitrypsin augmentation therapy slows the progression of emphysema. Augmentation therapy raises serum and lung alpha-1 antitrypsin levels and has been shown to slow the loss of lung density on CT, although it does not reverse established emphysema. Patients must also receive vaccinations, pulmonary rehabilitation, and bronchodilators, and they must avoid smoking and occupational dust exposure. Daily oral prednisone is not used for alpha-1 antitrypsin deficiency. Lung volume reduction surgery is not indicated for panacinar lower-lobe disease. An inhaled corticosteroid alone does not replace augmentation therapy. Theophylline is not a treatment for alpha-1 antitrypsin deficiency.', 'Hard', 26, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 38-year-old woman is found to have the PiZZ phenotype of alpha-1 antitrypsin deficiency on family screening. She is asymptomatic, has never smoked, and her FEV1 is normal. What is the most appropriate management?', '["Start augmentation therapy now", "Smoking avoidance, vaccinations, and periodic monitoring", "Daily inhaled corticosteroids", "Lung transplant evaluation", "Daily azithromycin"]'::jsonb, 1, 'An asymptomatic PiZZ individual with normal lung function does not need augmentation therapy, which is reserved for patients with established airflow obstruction and declining FEV1; trials show no proven benefit in the absence of lung disease. Management consists of strict smoking avoidance, since smoking is the major accelerator of emphysema in alpha-1 deficiency, plus influenza and pneumococcal vaccination and periodic spirometry to detect early decline. Daily inhaled corticosteroids are only for symptomatic obstructive disease with frequent exacerbations, not for an asymptomatic person. Lung transplant evaluation is reserved for end-stage disease, and daily azithromycin is an exacerbation-reduction strategy in selected COPD patients, not a preventive therapy here.', 'Medium', 27, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 62-year-old man with a 45 pack-year smoking history has a chronic productive cough for 3 months in each of the last 2 years. He is cyanotic with peripheral edema and polycythemia, and coarse rhonchi are heard on examination. What is the most likely diagnosis?', '["Emphysema (pink puffer)", "Asthma", "Chronic bronchitis (blue bloater)", "Bronchiectasis", "Pulmonary fibrosis"]'::jsonb, 2, 'Chronic bronchitis is defined clinically by a productive cough for at least 3 months in each of 2 consecutive years, and the classic blue bloater phenotype has cyanosis, peripheral edema and polycythemia from chronic hypoxemia and cor pulmonale, with coarse rhonchi from mucus in large airways. Emphysema, the pink puffer, presents instead with thin habitus, pursed-lip breathing, hyperinflation and minimal cough. Asthma is reversible airflow obstruction with episodic wheezing, not a chronic productive cough. Bronchiectasis produces large volumes of purulent sputum with dilated airways on imaging. Pulmonary fibrosis causes a restrictive pattern with a dry cough and fine crackles, not a productive cough.', 'Easy', 28, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 68-year-old man is thin, with a barrel-shaped chest and pursed-lip breathing. He has minimal cough, hyperresonance to percussion, decreased breath sounds, a low DLCO, and CT shows upper-lobe bullae. What is the most likely diagnosis?', '["Chronic bronchitis", "Asthma", "Bronchiectasis", "Emphysema (pink puffer)", "Congestive heart failure"]'::jsonb, 3, 'Emphysema, the classic pink puffer, presents with progressive dyspnea, a barrel-shaped chest from hyperinflation, pursed-lip breathing, minimal cough, hyperresonance to percussion and decreased breath sounds, with a reduced DLCO reflecting loss of alveolar surface area and upper-lobe bullae on CT from alveolar wall destruction. Chronic bronchitis instead causes a chronic productive cough with cyanosis and edema, the blue bloater. Asthma is reversible airflow obstruction with episodic wheeze rather than fixed hyperinflation. Bronchiectasis causes large volumes of purulent sputum with dilated airways. Heart failure causes orthopnea, peripheral edema and crackles rather than hyperinflation and bullae.', 'Medium', 29, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 66-year-old man with chronic bronchitis phenotype COPD asks which intervention will most improve his prognosis and survival. He continues to smoke one pack per day. Which of the following is the most important next step in his management?', '["Daily inhaled corticosteroid", "Long-acting bronchodilators", "Pulmonary rehabilitation", "Theophylline", "Smoking cessation"]'::jsonb, 4, 'Smoking cessation is the only intervention proven to improve survival and slow the decline in FEV1 in COPD, making it the single most important step in management; it should be offered with counselling and pharmacotherapy such as varenicline. Daily inhaled corticosteroids reduce exacerbations in patients with frequent exacerbations and higher eosinophils but do not improve mortality. Long-acting bronchodilators improve symptoms and reduce exacerbations without a proven mortality benefit. Pulmonary rehabilitation improves exercise capacity and quality of life but has not been shown to improve survival. Theophylline is a weak bronchodilator with a narrow therapeutic window and significant toxicity, and it is not a first-line intervention.', 'Medium', 30, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 45-year-old previously healthy woman presents with 3 days of fever to 38.5°C, productive cough with yellow sputum, and right-sided pleuritic chest pain. On examination she is alert with temperature 38.4°C, heart rate 92/min, respiratory rate 18/min, blood pressure 118/76 mmHg, and oxygen saturation 97% on room air. There are crackles over the right lower lung field, and chest X-ray shows a right lower lobe consolidation. Which of the following is the most appropriate treatment?', '["Admit for IV ceftriaxone plus azithromycin", "Vancomycin plus piperacillin-tazobactam", "Oral amoxicillin as an outpatient", "Oral levofloxacin plus prednisone", "Admit to the intensive care unit for monitoring"]'::jsonb, 2, 'This is community-acquired pneumonia in a healthy outpatient with a CURB-65 score of 0, so outpatient oral therapy is appropriate and Streptococcus pneumoniae is the most likely pathogen. Guidelines recommend amoxicillin, doxycycline, or a macrolide as monotherapy for healthy outpatients. Inpatient IV ceftriaxone plus azithromycin is reserved for admitted patients and is unnecessary here. Vancomycin plus piperacillin-tazobactam is broad-spectrum therapy for hospital-acquired pneumonia with MRSA and Pseudomonas risk, which she does not have. Prednisone is not routine therapy for mild pneumonia, and ICU admission is not indicated with normal oxygenation and stable vitals.', 'Medium', 31, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 78-year-old man is brought to the emergency department with 2 days of fever, productive cough, and increasing confusion. His temperature is 39.2°C, heart rate 118/min, respiratory rate 32/min, blood pressure 86/58 mmHg, and oxygen saturation 89% on room air. Laboratory studies show blood urea nitrogen 26 mg/dL. Chest X-ray reveals multilobar infiltrates. Which of the following is the most appropriate next step in management?', '["Discharge home on oral azithromycin", "Admit to the intensive care unit and start IV ceftriaxone plus azithromycin", "Oral amoxicillin-clavulanate as an outpatient", "Discharge with an inhaler and close follow-up", "IV vancomycin alone"]'::jsonb, 1, 'This patient has a CURB-65 score of 5 (confusion, urea >20, respiratory rate ≥30, low blood pressure, age ≥65), indicating severe community-acquired pneumonia with high mortality that requires intensive care. Severe pneumonia is treated with a beta-lactam plus a macrolide, such as IV ceftriaxone plus azithromycin, to cover pneumococcus and atypical organisms. Discharging him on oral therapy would be unsafe given his hypoxemia, hypotension, and confusion. Vancomycin alone does not cover Streptococcus pneumoniae or atypical pathogens adequately. An inhaler does not treat pneumonia.', 'Hard', 32, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 21-year-old college student presents with 1 week of dry cough, low-grade fever, headache, sore throat, and ear pain. Examination reveals bullous myringitis. Her white blood cell count is normal, and chest X-ray shows diffuse bilateral interstitial infiltrates. Cold agglutinin testing is positive. Which of the following is the most appropriate treatment?', '["Amoxicillin", "Ceftriaxone", "Vancomycin", "Azithromycin", "Oseltamivir"]'::jsonb, 3, 'This is atypical pneumonia caused by Mycoplasma pneumoniae, suggested by the patient''s young age, extrapulmonary features including bullous myringitis, normal white blood cell count, interstitial infiltrates, and positive cold agglutinins. Mycoplasma lacks a cell wall, so beta-lactam antibiotics such as amoxicillin and ceftriaxone are ineffective. A macrolide such as azithromycin is the treatment of choice because it covers atypical organisms. Vancomycin is reserved for suspected MRSA infection, which is not suggested here. Oseltamivir treats influenza, but the subacute course with extrapulmonary findings points to Mycoplasma rather than influenza.', 'Medium', 33, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 66-year-old man with community-acquired pneumonia is admitted to the hospital. He is confused, with respiratory rate 34/min, blood pressure 100/60 mmHg on intravenous fluids, blood urea nitrogen 24 mg/dL, and PaO2/FiO2 ratio of 210. Chest X-ray shows multilobar infiltrates. Which of the following is the most appropriate next step in management?', '["Transfer to the intensive care unit and start IV ceftriaxone plus azithromycin", "Discharge home on oral doxycycline", "Add vancomycin only", "Nebulized bronchodilator therapy only", "Discharge after one dose of IV ceftriaxone"]'::jsonb, 0, 'This patient meets criteria for severe community-acquired pneumonia: he has multiple minor criteria including respiratory rate ≥30, PaO2/FiO2 ≤250, confusion, blood urea nitrogen ≥20, and multilobar infiltrates, so he requires ICU admission. Severe pneumonia should be treated with combination therapy, a beta-lactam plus a macrolide such as ceftriaxone plus azithromycin, to cover pneumococcus, atypicals, and other pathogens. Discharging him on oral therapy would be dangerous given his hypoxemia and confusion. Vancomycin alone is insufficient coverage, and bronchodilators do not treat the underlying infection.', 'Hard', 34, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 72-year-old man is on postoperative day 6 after bowel surgery when he develops fever to 39.0°C, purulent sputum, and a new right lower lobe infiltrate. He received perioperative antibiotics and is known to be colonized with methicillin-resistant Staphylococcus aureus (MRSA). His oxygen saturation is 91% on room air. Which of the following is the most appropriate empiric antibiotic regimen?', '["Ceftriaxone alone", "Azithromycin alone", "Oral amoxicillin", "Supportive care without antibiotics", "Vancomycin plus piperacillin-tazobactam"]'::jsonb, 4, 'This is late-onset hospital-acquired pneumonia (day 6) in a patient with prior antibiotic exposure and known MRSA colonization, placing him at high risk for multidrug-resistant organisms including MRSA and Pseudomonas aeruginosa. Empiric therapy must therefore include vancomycin for MRSA plus an antipseudomonal beta-lactam such as piperacillin-tazobactam. Ceftriaxone alone lacks activity against MRSA and Pseudomonas. Azithromycin alone is inadequate for hospital-acquired pneumonia, and oral amoxicillin is too narrow. Supportive care without antibiotics is inappropriate for a febrile patient with a new infiltrate and hypoxemia.', 'Medium', 35, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 58-year-old woman has been intubated for 5 days after a motor vehicle accident. She develops fever to 38.8°C, purulent endotracheal secretions, a white blood cell count of 14,000/µL, and a new left lower lobe infiltrate on chest X-ray. Which of the following is the most appropriate next step in management?', '["Extubate immediately and observe", "Obtain endotracheal aspirate cultures and start empiric antibiotics", "Chest physiotherapy alone", "High-dose intravenous corticosteroids", "Bronchoscopy for biopsy only"]'::jsonb, 1, 'This patient meets clinical criteria for ventilator-associated pneumonia: fever, leukocytosis, purulent secretions, and a new infiltrate after more than 48 hours of mechanical ventilation. The correct next step is to obtain respiratory cultures (endotracheal aspirate or bronchoalveolar lavage) before starting empiric antibiotics, which should cover likely organisms based on local resistance patterns. Immediate extubation is not appropriate while she has pneumonia and respiratory failure. Chest physiotherapy alone does not treat infection, corticosteroids are not indicated for ventilator-associated pneumonia, and biopsy alone would delay needed antibiotics.', 'Medium', 36, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 55-year-old man develops fever to 38.6°C, cough, and a right middle lobe infiltrate on postoperative day 3 after hip replacement. He has received no prior antibiotics, has no known colonization with resistant organisms, and is hemodynamically stable. Which of the following is the most appropriate empiric antibiotic regimen?', '["Vancomycin plus cefepime plus levofloxacin", "Oral doxycycline", "Intravenous ceftriaxone", "Amphotericin B", "No antibiotics, observation only"]'::jsonb, 2, 'This is early-onset hospital-acquired pneumonia (within 4 days of admission) in a patient without risk factors for multidrug-resistant organisms, so narrow-spectrum therapy is appropriate. Intravenous ceftriaxone, or ampicillin-sulbactam, covers the typical organisms including Streptococcus pneumoniae, Haemophilus influenzae, and methicillin-sensitive Staphylococcus aureus. Triple therapy with vancomycin, cefepime, and levofloxacin is excessive and promotes resistance when no MDR risk factors exist. Oral doxycycline is inadequate for hospital-acquired pneumonia, amphotericin treats fungal infection which is not suggested, and observation is inappropriate for a febrile patient with a new infiltrate.', 'Medium', 37, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 64-year-old man with ventilator-associated pneumonia is improving on day 3 of vancomycin plus cefepime. Endotracheal aspirate cultures grow methicillin-sensitive Staphylococcus aureus (MSSA) only, and he is now afebrile with a decreasing white blood cell count. Which of the following is the most appropriate next step?', '["Continue both antibiotics for 14 days", "Add amphotericin B", "Stop all antibiotics", "Narrow to cefazolin and stop vancomycin", "Switch to oral azithromycin"]'::jsonb, 3, 'Once cultures identify the causative organism, therapy should be de-escalated to targeted treatment. MSSA is best treated with a narrow-spectrum beta-lactam such as cefazolin or nafcillin, and vancomycin can be stopped because there is no MRSA. Continuing broad-spectrum therapy unnecessarily promotes resistance, Clostridioides difficile infection, and drug toxicity. Stopping all antibiotics on day 3 is premature, as ventilator-associated pneumonia typically requires 7 days of therapy. Amphotericin B is an antifungal with no role here, and azithromycin does not adequately treat MSSA pneumonia.', 'Hard', 38, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'An 81-year-old man with a recent stroke and dysphagia presents with 4 days of fever, cough, and shortness of breath. He has poor dentition. Chest X-ray shows a right lower lobe infiltrate. His oxygen saturation is 92% on room air. Which of the following is the most appropriate antibiotic regimen?', '["Ampicillin-sulbactam", "Azithromycin alone", "Oseltamivir", "Vancomycin alone", "Inhaled corticosteroids"]'::jsonb, 0, 'This is aspiration pneumonia following a stroke with dysphagia, involving oral anaerobes plus aerobic organisms such as Streptococcus pneumoniae and Haemophilus influenzae. Ampicillin-sulbactam covers both anaerobes and these aerobes, making it appropriate first-line therapy. Azithromycin alone lacks anaerobic coverage and is insufficient for aspiration pneumonia. Oseltamivir treats influenza, which is not the diagnosis here. Vancomycin alone misses anaerobes and gram-negative organisms. Inhaled corticosteroids have no role in treating acute bacterial pneumonia. Clindamycin is an acceptable alternative because it also covers oral anaerobes well.', 'Medium', 39, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 54-year-old man has a witnessed large-volume aspiration of gastric contents during a seizure. Within 2 hours he develops acute dyspnea and hypoxemia, with diffuse bilateral infiltrates on chest X-ray. He is afebrile with a normal white blood cell count and no purulent sputum. Which of the following is the most appropriate management?', '["Start broad-spectrum antibiotics immediately", "Emergent bronchoscopy with lavage", "High-dose intravenous corticosteroids", "Intravenous vancomycin", "Supportive care with oxygen and observation"]'::jsonb, 4, 'This presentation is aspiration pneumonitis (Mendelson syndrome), a chemical injury from aspirated gastric acid, not bacterial pneumonia. It develops within hours of aspiration, causes diffuse infiltrates and hypoxemia, and is initially sterile, so antibiotics are not indicated unless bacterial superinfection develops. Supportive care with oxygen, monitoring, and observation is the mainstay of treatment. Broad-spectrum antibiotics and vancomycin expose the patient to unnecessary drugs and resistance. Corticosteroids have not been shown to improve outcomes in aspiration pneumonitis, and emergent bronchoscopy is not first-line therapy.', 'Medium', 40, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 48-year-old man with chronic alcohol use presents with 2 weeks of fever, foul-smelling sputum, and weight loss. He has poor dentition and a right lower lobe infiltrate on chest X-ray. Sputum Gram stain shows mixed flora with many polymorphonuclear cells. Which of the following is the most appropriate treatment?', '["Isoniazid plus rifampin", "Azithromycin", "Clindamycin", "Amphotericin B", "Oseltamivir"]'::jsonb, 2, 'This is anaerobic aspiration pneumonia, suggested by alcohol use, poor dentition, putrid-smelling sputum, and a dependent right lower lobe infiltrate. Clindamycin provides excellent coverage against oral anaerobes and is the classic treatment for anaerobic aspiration pneumonia. Isoniazid plus rifampin is tuberculosis therapy, which is not the diagnosis here. Azithromycin lacks anaerobic activity and would not cover the causative organisms. Amphotericin B treats fungal infection, and oseltamivir treats influenza, neither of which fits this subacute anaerobic presentation. Treatment is typically prolonged over several weeks, with drainage reserved for large or refractory abscesses.', 'Medium', 41, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 34-year-old man who recently immigrated presents with 3 months of cough, night sweats, and 8-kg weight loss. Chest X-ray shows an upper lobe cavitary lesion. Sputum acid-fast bacillus smear is positive. Which of the following is the most appropriate next step in management?', '["Outpatient amoxicillin", "Airborne isolation and start RIPE therapy", "Discharge home on azithromycin", "Prednisone alone", "Sputum culture only, with no treatment"]'::jsonb, 1, 'This patient has active pulmonary tuberculosis, indicated by chronic cough, constitutional symptoms, an upper lobe cavity, and a positive acid-fast bacillus smear. He must be placed in airborne isolation immediately to prevent transmission, and treatment should be started promptly with RIPE therapy (rifampin, isoniazid, pyrazinamide, and ethambutol). Waiting for culture results before treating would delay therapy and prolong infectivity. Amoxicillin and azithromycin are ineffective against Mycobacterium tuberculosis, and prednisone alone does not treat tuberculosis. Nucleic acid amplification testing on sputum can confirm the diagnosis rapidly while cultures are pending.', 'Medium', 42, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 29-year-old female healthcare worker has a positive interferon-gamma release assay (IGRA) for tuberculosis. She is asymptomatic, chest X-ray is normal, and she is HIV-negative. Which of the following is the most appropriate management?', '["RIPE therapy", "No treatment, repeat chest X-ray in 1 year", "Airborne isolation", "Isoniazid daily for 9 months", "Prednisone"]'::jsonb, 3, 'This patient has latent tuberculosis infection: a positive IGRA with a normal chest X-ray and no symptoms, meaning she is infected but not contagious and has no active disease. She should receive prophylactic treatment to prevent reactivation, and isoniazid daily for 9 months (or rifampin daily for 4 months) is a standard regimen. RIPE therapy with four drugs is reserved for active tuberculosis and would be overtreatment. Airborne isolation is unnecessary because latent tuberculosis is not infectious. Observation alone leaves her at risk of developing active disease, and prednisone has no role in latent tuberculosis.', 'Easy', 43, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 41-year-old man has been taking RIPE therapy for pulmonary tuberculosis for 2 months. He now reports blurred vision and difficulty distinguishing red from green colors. Which of the following is the most appropriate next step?', '["Stop ethambutol", "Stop rifampin", "Stop isoniazid", "Add prednisone", "Continue all drugs unchanged"]'::jsonb, 0, 'Ethambutol causes dose-dependent optic neuritis, presenting with decreased visual acuity and red-green color blindness, and it should be stopped promptly to prevent permanent vision loss. Rifampin more commonly causes hepatotoxicity, orange discoloration of urine and tears, and drug interactions rather than visual changes. Isoniazid is associated with peripheral neuropathy and hepatotoxicity, not optic neuritis. Continuing all drugs risks irreversible blindness, and adding prednisone does not address the drug toxicity. Vision should be checked at baseline and monitored during ethambutol therapy so toxicity is detected early.', 'Medium', 44, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 38-year-old man with a history of previously treated tuberculosis has sputum cultures showing resistance to both isoniazid and rifampin. Which of the following is the most appropriate next step in management?', '["Continue RIPE therapy", "Amoxicillin-clavulanate", "Stop all therapy", "Isoniazid alone", "Refer to a tuberculosis specialist for a second-line regimen guided by drug-susceptibility testing"]'::jsonb, 4, 'Resistance to both isoniazid and rifampin defines multidrug-resistant tuberculosis (MDR-TB). Standard RIPE therapy will fail because the two most effective first-line drugs are ineffective, so continuing it risks treatment failure and further resistance. Management requires referral to a tuberculosis specialist for a second-line regimen based on drug-susceptibility testing, typically including a fluoroquinolone and other agents such as bedaquiline or linezolid. Amoxicillin-clavulanate has no activity against Mycobacterium tuberculosis, and stopping all therapy would allow the disease to progress and spread. Directly observed therapy and public health reporting are also important parts of tuberculosis management.', 'Hard', 45, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 42-year-old man with HIV and a CD4 count of 85 cells/µL presents with 3 weeks of progressive dyspnea, dry cough, and low-grade fever. His oxygen saturation is 88% on room air. Chest X-ray shows bilateral perihilar interstitial infiltrates, and lactate dehydrogenase is 520 U/L. Which of the following is the most appropriate treatment?', '["Ceftriaxone plus azithromycin", "Amphotericin B", "Trimethoprim-sulfamethoxazole plus prednisone", "Oseltamivir", "Vancomycin"]'::jsonb, 2, 'This is Pneumocystis jirovecii pneumonia in advanced HIV with a CD4 count below 200, suggested by subacute dyspnea, dry cough, hypoxemia, bilateral interstitial infiltrates, and elevated lactate dehydrogenase. Trimethoprim-sulfamethoxazole is the treatment of choice. Prednisone is added when hypoxemia is severe (PaO2 below 70 mmHg or alveolar-arterial gradient of 35 mmHg or greater) because it reduces mortality. Ceftriaxone plus azithromycin treats bacterial pneumonia but misses Pneumocystis. Amphotericin B treats invasive fungal infection, and oseltamivir treats influenza, neither of which fits this presentation.', 'Medium', 46, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 33-year-old man who recently explored caves in the Ohio River valley presents with 2 weeks of fever, cough, and myalgias. Chest X-ray shows diffuse reticulonodular infiltrates, and urine Histoplasma antigen is positive. He is moderately ill with dyspnea on exertion. Which of the following is the most appropriate treatment?', '["Observation only", "Itraconazole", "Amphotericin B alone for mild disease", "RIPE therapy", "Azithromycin"]'::jsonb, 1, 'This is acute pulmonary histoplasmosis acquired from exposure to bird or bat droppings in the Ohio-Mississippi River valley, confirmed by a positive urine antigen test. Moderate disease with dyspnea should be treated with itraconazole for 6 to 12 weeks. Amphotericin B is reserved for severe or disseminated disease, not moderate pulmonary disease. Observation is appropriate only for mild, asymptomatic infection. RIPE therapy treats tuberculosis, not histoplasmosis, and azithromycin has no activity against Histoplasma capsulatum. Severe disease with respiratory failure is treated with liposomal amphotericin B followed by itraconazole.', 'Medium', 47, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 28-year-old woman living in Arizona presents with 3 weeks of cough, fever, and painful red nodules on her shins. Chest X-ray shows a right lower lobe infiltrate with hilar adenopathy. Which of the following is the most appropriate treatment?', '["RIPE therapy", "Ceftriaxone", "Observation only", "Fluconazole", "Vancomycin"]'::jsonb, 3, 'This is coccidioidomycosis, an endemic fungal infection of the southwestern United States, suggested by residence in Arizona, pulmonary infiltrate, and erythema nodosum, which is a hypersensitivity reaction associated with the infection. Symptomatic or persistent pulmonary coccidioidomycosis is treated with fluconazole. RIPE therapy treats tuberculosis, ceftriaxone and vancomycin treat bacterial pneumonia, and none are effective against Coccidioides. Observation may be reasonable for mild, self-limited disease, but her persistent symptoms and erythema nodosum warrant antifungal therapy. Most mild infections resolve without treatment, but symptomatic disease should not be left untreated when it persists.', 'Medium', 48, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 55-year-old man with acute myeloid leukemia is neutropenic on day 12 of induction chemotherapy. He has persistent fever despite broad-spectrum antibiotics, and chest CT shows a pulmonary nodule with a surrounding halo of ground-glass opacity. Which of the following is the most appropriate treatment?', '["Voriconazole", "Fluconazole", "Itraconazole", "Caspofungin alone", "Vancomycin"]'::jsonb, 0, 'This is invasive pulmonary aspergillosis, suggested by prolonged neutropenia, fever refractory to antibacterial therapy, and the halo sign on chest CT. Voriconazole is the first-line treatment of choice for invasive aspergillosis. Fluconazole has no activity against Aspergillus species, so it would be ineffective. Itraconazole is less effective and has variable absorption. Caspofungin is used as salvage therapy, not first-line treatment. Vancomycin treats gram-positive bacterial infection, which does not explain the halo sign in a neutropenic patient. Treatment is continued until neutropenia resolves and imaging improves, with therapeutic drug monitoring of voriconazole levels.', 'Hard', 49, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 68-year-old man with a 50 pack-year smoking history presents with 2 months of cough, weight loss, and a central hilar mass on chest X-ray. Laboratory studies show sodium 122 mEq/L with low serum osmolality and high urine osmolality, and normal thyroid and adrenal function. Which of the following is the most likely diagnosis?', '["Squamous cell carcinoma", "Adenocarcinoma", "Mesothelioma", "Pulmonary embolism", "Small cell lung cancer"]'::jsonb, 4, 'Small cell lung cancer is a central tumor strongly associated with heavy smoking that frequently causes paraneoplastic syndrome of inappropriate antidiuretic hormone secretion (SIADH), producing hyponatremia with low serum osmolality and inappropriately concentrated urine. It can also cause ectopic ACTH secretion. Adenocarcinoma is typically peripheral and occurs more often in never-smokers. Squamous cell carcinoma more commonly causes hypercalcemia through parathyroid hormone-related protein. Mesothelioma is a pleural tumor associated with asbestos exposure, and pulmonary embolism does not cause a hilar mass with SIADH.', 'Medium', 50, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 58-year-old woman who has never smoked presents with a peripheral 3-cm lung nodule. Biopsy shows adenocarcinoma, and molecular testing is positive for an EGFR mutation. Which of the following is the most appropriate next step in management?', '["Surgical resection without staging", "Cisplatin plus etoposide chemotherapy", "Complete staging with PET-CT and brain MRI, then EGFR-targeted therapy", "Whole-brain radiation alone", "Observation"]'::jsonb, 2, 'Adenocarcinoma is the most common lung cancer in never-smokers and frequently harbors EGFR mutations. Before any treatment, complete staging with PET-CT and brain MRI is required to determine the extent of disease, after which an EGFR tyrosine kinase inhibitor such as osimertinib is the preferred therapy for EGFR-mutant disease. Surgical resection without staging risks missing metastatic disease. Cisplatin plus etoposide is the standard regimen for small cell lung cancer, not adenocarcinoma. Whole-brain radiation alone is not appropriate without staging, and observation would delay effective targeted treatment.', 'Hard', 51, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 62-year-old man with a 30 pack-year smoking history who currently smokes is asymptomatic and asks about lung cancer screening. Which of the following is the most appropriate screening recommendation?', '["Annual chest X-ray", "Annual low-dose CT", "Sputum cytology", "No screening is recommended", "PET-CT annually"]'::jsonb, 1, 'Annual low-dose CT is recommended for lung cancer screening in adults aged 50 to 80 years with at least a 20 pack-year smoking history who currently smoke or quit within the past 15 years. This patient meets all criteria. Low-dose CT has been shown to reduce lung cancer mortality, whereas chest X-ray and sputum cytology have not been shown to be effective screening tools. PET-CT is not used for screening because of high cost and radiation exposure. No screening would miss the opportunity for early detection in this high-risk patient.', 'Easy', 52, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 64-year-old man with a long smoking history presents with facial swelling, dilated veins over the neck and upper chest, and dyspnea. Chest X-ray shows a right upper lobe mass. Which of the following is the most appropriate next step in management?', '["Diuretics alone", "Anticoagulation for pulmonary embolism", "High-dose antibiotics", "Urgent tissue diagnosis followed by chemotherapy or radiation, with consideration of superior vena cava stenting", "Outpatient follow-up in 3 months"]'::jsonb, 3, 'This is superior vena cava syndrome caused by obstruction from a lung mass, most likely lung cancer. The appropriate management is urgent tissue diagnosis followed by definitive cancer treatment with chemotherapy or radiation, and endovascular stenting can provide rapid relief of severe symptoms. Diuretics alone do not relieve the mechanical obstruction, and anticoagulation treats pulmonary embolism, which does not explain the facial swelling and dilated veins. Antibiotics do not treat a malignant obstruction, and outpatient follow-up in 3 months would dangerously delay treatment of a progressive, potentially life-threatening condition.', 'Hard', 53, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 52-year-old man with chronic alcohol use presents with 3 weeks of fever and foul-smelling sputum. Chest X-ray shows a right lower lobe cavity with an air-fluid level. Which of the following is the most appropriate treatment?', '["Clindamycin for 4 to 6 weeks", "Isoniazid plus rifampin", "Azithromycin for 5 days", "Immediate surgical lobectomy", "Amphotericin B"]'::jsonb, 0, 'This is an anaerobic lung abscess, suggested by alcohol use, putrid-smelling sputum, and a cavitary lesion with an air-fluid level in a dependent lung segment. Clindamycin provides excellent coverage against oral anaerobes and is the treatment of choice, given for 4 to 6 weeks until the cavity resolves. Isoniazid plus rifampin is tuberculosis therapy and is not indicated here. Azithromycin lacks anaerobic activity and a 5-day course is far too short for a lung abscess. Immediate surgery is reserved for refractory cases or complications such as massive hemoptysis, and amphotericin B treats fungal infection.', 'Medium', 54, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 60-year-old man recovering from pneumonia develops recurrent fever and pleuritic chest pain. Chest X-ray shows a loculated pleural effusion. Thoracentesis reveals pleural fluid pH 7.05, glucose 28 mg/dL, and lactate dehydrogenase 1400 U/L. Which of the following is the most appropriate next step in management?', '["Continue antibiotics alone", "Diuretics", "Single therapeutic thoracentesis", "Prednisone", "Chest tube drainage"]'::jsonb, 4, 'This is a complicated parapneumonic effusion progressing to empyema, indicated by a pleural fluid pH below 7.2, very low glucose, and markedly elevated lactate dehydrogenase. Such effusions require drainage with a chest tube in addition to antibiotics, because antibiotics alone cannot sterilize a loculated infected collection. A single therapeutic thoracentesis is insufficient for ongoing drainage of empyema. Diuretics treat transudative effusions from heart failure, not infected exudates, and prednisone has no role in empyema management. Fibrinolytics or surgical decortication may be needed if chest tube drainage fails to clear the infection.', 'Medium', 55, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 47-year-old man presents with fever, cough, and a cavitary lesion on chest X-ray. The team needs to distinguish a lung abscess from an empyema. Which of the following is the best initial test?', '["Sputum acid-fast bacillus smear", "Thoracentesis alone", "Contrast-enhanced chest CT", "Ventilation-perfusion scan", "Bronchoscopy with biopsy"]'::jsonb, 2, 'Contrast-enhanced chest CT is the best test to distinguish a lung abscess from an empyema. A lung abscess appears as a parenchymal cavity with an air-fluid level, while an empyema appears as a lentiform pleural collection with the split pleura sign. Thoracentesis alone samples pleural fluid but does not characterize the lesion or show its anatomic relationship to the lung. Sputum acid-fast bacillus smear evaluates for tuberculosis, a ventilation-perfusion scan evaluates for pulmonary embolism, and bronchoscopy with biopsy is not the initial test for distinguishing these two entities.', 'Hard', 56, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 68-year-old woman with chronic obstructive pulmonary disease presents with 2 days of fever to 39.0°C, severe myalgias, and dry cough. Rapid influenza antigen testing is positive for influenza A. Which of the following is the most appropriate treatment?', '["Amoxicillin", "Oseltamivir", "Azithromycin", "Vancomycin", "Supportive care only"]'::jsonb, 1, 'This patient has confirmed influenza A infection, and oseltamivir is the appropriate antiviral treatment. It is most effective when started within 48 hours of symptom onset, and it is also recommended for hospitalized patients, those with severe disease, and high-risk patients such as this woman with chronic obstructive pulmonary disease even after 48 hours. Amoxicillin, azithromycin, and vancomycin are antibiotics that treat bacterial pneumonia, not influenza. Supportive care alone would miss the benefit of antiviral therapy in a high-risk patient with confirmed influenza.', 'Easy', 57, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 26-year-old man presents with 5 days of fever, dry cough, and shortness of breath. Chest X-ray shows bilateral interstitial infiltrates. His white blood cell count is 5,000/µL with lymphopenia, sputum cultures are negative, and he reports several sick contacts at work. Which of the following is the most appropriate management?', '["Vancomycin plus piperacillin-tazobactam", "RIPE therapy", "Amphotericin B", "Supportive care with monitoring and testing for viral pathogens", "High-dose corticosteroids"]'::jsonb, 3, 'This presentation is most consistent with viral pneumonia, suggested by the subacute course, dry cough, bilateral interstitial infiltrates, lymphopenia, and negative bacterial cultures in the setting of sick contacts. Management is supportive care with monitoring and testing to identify the virus, such as influenza, respiratory syncytial virus, or SARS-CoV-2. Broad-spectrum antibiotics such as vancomycin plus piperacillin-tazobactam are not indicated without evidence of bacterial infection. RIPE therapy treats tuberculosis and amphotericin B treats fungal infection, neither of which fits this picture, and high-dose corticosteroids are not routine therapy for viral pneumonia.', 'Medium', 58, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 70-year-old man had influenza 1 week ago and was improving, but he now develops high fever, productive cough, and a new right upper lobe infiltrate. Sputum Gram stain shows gram-positive cocci in clusters. Which of the following is the most appropriate empiric therapy?', '["Vancomycin plus ceftriaxone", "Oseltamivir alone", "Azithromycin alone", "RIPE therapy", "Amphotericin B"]'::jsonb, 0, 'This is secondary bacterial pneumonia following influenza, classically caused by Staphylococcus aureus, including methicillin-resistant strains, after initial viral improvement. Empiric therapy should therefore include vancomycin for MRSA coverage plus ceftriaxone to cover Streptococcus pneumoniae. Oseltamivir alone treats influenza but does not address the new bacterial superinfection. Azithromycin alone is inadequate for suspected MRSA pneumonia. RIPE therapy treats tuberculosis and amphotericin B treats fungal infection, neither of which explains this biphasic illness with gram-positive cocci in clusters. Influenza vaccination remains the best prevention, but it does not eliminate the risk of secondary bacterial infection.', 'Medium', 59, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 28-year-old woman at 24 weeks of gestation presents with 1 day of fever, cough, and myalgias. Rapid testing is positive for influenza A. Which of the following is the most appropriate next step?', '["Reassure and give no treatment because she is pregnant", "Amoxicillin", "Wait 48 hours before deciding on treatment", "Admit for intravenous vancomycin", "Start oseltamivir promptly"]'::jsonb, 4, 'Pregnant women are at high risk for severe influenza complications, including pneumonia and respiratory failure, so antiviral treatment should not be withheld. Oseltamivir is safe in pregnancy and should be started promptly, ideally within 48 hours of symptom onset, to reduce the risk of severe disease. Reassurance without treatment would leave a high-risk patient unprotected. Amoxicillin and vancomycin are antibiotics that do not treat influenza. Waiting 48 hours before deciding would delay therapy and worsen outcomes in pregnancy. Treatment should not be delayed for confirmatory testing when influenza is suspected in a pregnant patient.', 'Medium', 60, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 68-year-old woman is 3 days post total hip replacement when she develops sudden dyspnea, pleuritic chest pain, and diaphoresis. Her blood pressure is 82/55 mmHg, heart rate 128/min, respiratory rate 28/min, and oxygen saturation 88% on room air. Examination shows jugular venous distention and a loud P2. ECG shows sinus tachycardia with an S1Q3T3 pattern, and bedside echocardiography shows a dilated, hypokinetic right ventricle. Which of the following is the most appropriate next step in management?', '["Intravenous unfractionated heparin alone", "CT pulmonary angiography before any treatment", "Intravenous fluids and norepinephrine only", "Surgical pulmonary embolectomy", "Systemic thrombolysis with alteplase"]'::jsonb, 4, 'This is a massive (high-risk) pulmonary embolism with obstructive shock: hypotension, tachycardia, right ventricular strain on echocardiography, and ECG changes after recent major surgery. Systemic thrombolysis is first-line in massive PE with shock because it rapidly dissolves clot and restores pulmonary perfusion. Heparin alone prevents propagation but does not relieve obstruction fast enough in shock. CT angiography would delay life-saving therapy when the clinical picture and bedside echo already establish the diagnosis. Vasopressors and fluids support blood pressure but do not treat the clot. Surgical embolectomy is reserved for thrombolysis failure or contraindication, not first-line.', 'Hard', 61, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 32-year-old woman presents to the emergency department with 2 hours of sharp, pleuritic left-sided chest pain that began during a long-haul flight. She has no leg swelling or pain, no hemoptysis, no prior venous thromboembolism, no recent surgery, no estrogen use, and no history of cancer. Her heart rate is 88/min, oxygen saturation is 98% on room air, and her examination is normal. Her PERC score is 0. Which of the following is the most appropriate next step?', '["No further testing; discharge with return precautions", "D-dimer level", "CT pulmonary angiography", "Lower extremity duplex ultrasonography", "Ventilation-perfusion scan"]'::jsonb, 0, 'In a low-risk patient with a negative PERC rule (age <50, heart rate <100, oxygen saturation >94%, no hemoptysis, no estrogen use, no prior VTE, no unilateral leg swelling, no recent surgery/trauma), pulmonary embolism is effectively excluded and no further testing is needed. Ordering a D-dimer would only add false positives and unnecessary imaging in this population. CT pulmonary angiography exposes her to radiation and contrast without indication. Duplex ultrasound is not indicated without leg symptoms or signs of DVT. A V/Q scan is an alternative imaging test for PE but is unnecessary when PE has already been ruled out clinically.', 'Medium', 62, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 55-year-old man presents with 6 hours of dyspnea and pleuritic right-sided chest pain. He has no leg symptoms. His heart rate is 104/min, respiratory rate 22/min, and oxygen saturation is 94% on room air. His Wells score is 4.5, placing him at moderate risk for pulmonary embolism, and his D-dimer is elevated. Which of the following is the most appropriate next step?', '["Discharge home with outpatient follow-up", "Ventilation-perfusion scan", "CT pulmonary angiography", "Start heparin and observe without imaging", "Transthoracic echocardiography"]'::jsonb, 2, 'With moderate pretest probability and a positive D-dimer, CT pulmonary angiography is the diagnostic test of choice for pulmonary embolism because it directly visualizes the pulmonary arteries and confirms or excludes the diagnosis. A V/Q scan is reserved for patients in whom CT angiography is contraindicated, such as severe contrast allergy or renal failure. Heparin without imaging does not establish the diagnosis and commits the patient to anticoagulation unnecessarily. Echocardiography can show right ventricular strain but cannot diagnose or exclude PE. Discharging a moderately high-risk patient with a positive D-dimer is unsafe.', 'Medium', 63, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 45-year-old man had an unprovoked pulmonary embolism 6 months ago and has completed 6 months of apixaban without bleeding. He has no cancer, no prior venous thromboembolism, and no thrombophilia on testing. He is otherwise healthy and asks how long he should continue anticoagulation. Which of the following is the most appropriate recommendation?', '["Stop anticoagulation now", "Continue indefinite anticoagulation", "Switch to aspirin alone", "Place an inferior vena cava filter", "Repeat CT pulmonary angiography to decide"]'::jsonb, 1, 'An unprovoked (idiopathic) pulmonary embolism carries a high recurrence risk of roughly 10% per year after stopping anticoagulation, so extended indefinite anticoagulation is recommended when bleeding risk is low. Stopping after 6 months leaves him exposed to recurrence. Aspirin alone is substantially less effective than anticoagulation for secondary prevention. An inferior vena cava filter prevents embolization but does not prevent recurrent thrombosis and is indicated only when anticoagulation is contraindicated. Repeat imaging does not determine treatment duration, which is guided by whether the event was provoked or unprovoked and by bleeding risk.', 'Medium', 64, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 60-year-old woman presents with 3 days of progressive left leg swelling and aching pain. The calf is tender and 3 cm larger in circumference than the right. She has no chest pain or dyspnea. Which of the following is the most appropriate initial diagnostic test?', '["D-dimer level alone", "CT venography", "Magnetic resonance venography", "Compression duplex ultrasonography", "Contrast venography"]'::jsonb, 3, 'Compression duplex ultrasonography is the first-line test for suspected deep vein thrombosis because it is noninvasive, widely available, and highly sensitive for proximal DVT. A D-dimer can exclude DVT in low-probability patients but cannot confirm it and is often elevated for other reasons. CT and MR venography are reserved for equivocal ultrasound results or suspected pelvic or inferior vena cava thrombosis. Contrast venography is the historical gold standard but is invasive, requires contrast and radiation, and is rarely used now that ultrasound is available.', 'Easy', 65, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 52-year-old man is diagnosed with an acute proximal deep vein thrombosis of the left femoral vein. He has no cancer, normal renal function, no history of bleeding, and is not taking interacting medications. Which of the following is the most appropriate treatment?', '["Warfarin alone", "Apixaban", "Inferior vena cava filter", "Catheter-directed thrombolysis", "Aspirin alone"]'::jsonb, 1, 'A direct oral anticoagulant such as apixaban is preferred over warfarin for acute non-cancer venous thromboembolism because it requires no bridging or routine monitoring, has fewer drug interactions, and causes less major bleeding. Warfarin alone is inadequate acutely because it takes days to become therapeutic and requires heparin bridging. An IVC filter is indicated only when anticoagulation is contraindicated or has failed. Thrombolysis is reserved for limb-threatening phlegmasia cerulea dolens. Aspirin is an antiplatelet agent and is not sufficient treatment for acute DVT.', 'Medium', 66, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 58-year-old woman with metastatic pancreatic cancer presents with an acute proximal deep vein thrombosis of the right leg. Her platelet count is 180,000/uL, creatinine is normal, and she has no bleeding. Which of the following is the most appropriate anticoagulant?', '["Warfarin", "Unfractionated heparin", "Aspirin plus clopidogrel", "Inferior vena cava filter", "Low-molecular-weight heparin"]'::jsonb, 4, 'Low-molecular-weight heparin is preferred for cancer-associated venous thromboembolism, particularly with luminal gastrointestinal malignancy such as pancreatic cancer, because direct oral anticoagulants increase gastrointestinal bleeding in these patients. Warfarin is less effective in cancer, is difficult to keep therapeutic during chemotherapy and variable oral intake, and requires frequent INR monitoring. Unfractionated heparin requires hospitalization with continuous infusion and aPTT monitoring. Antiplatelet agents do not treat venous thrombosis. An inferior vena cava filter prevents embolization but does not treat the clot and is indicated only when anticoagulation is contraindicated.', 'Medium', 67, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 38-year-old woman has 8 months of progressive exertional dyspnea and fatigue. Examination shows a loud P2 and a right ventricular heave. Echocardiography shows a right ventricular systolic pressure of 68 mmHg with a dilated right ventricle and normal left ventricular function. Chest CT shows no thromboembolism or interstitial disease, and pulmonary function tests are normal. Which of the following is the most appropriate next step to confirm the diagnosis?', '["Right heart catheterization", "Repeat echocardiography", "High-resolution chest CT", "Ventilation-perfusion scan", "Pulmonary function tests with DLCO"]'::jsonb, 0, 'Right heart catheterization is the gold standard to confirm pulmonary arterial hypertension, directly measuring mean pulmonary artery pressure, pulmonary vascular resistance, and pulmonary capillary wedge pressure. Echocardiography only estimates pressures and cannot confirm the diagnosis. High-resolution CT and pulmonary function tests help exclude other causes but do not establish pulmonary hypertension. A V/Q scan is used to exclude chronic thromboembolic disease, a different group of pulmonary hypertension, but does not confirm group 1 disease. Hemodynamic confirmation by catheterization is required before starting PAH-specific therapy.', 'Medium', 68, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 72-year-old man with heart failure with reduced ejection fraction (ejection fraction 30%) has worsening exertional dyspnea. Echocardiography shows an estimated right ventricular systolic pressure of 55 mmHg with left atrial enlargement and no valvular disease. Which of the following is the most appropriate management of his pulmonary hypertension?', '["Start sildenafil", "Start bosentan", "Optimize guideline-directed heart failure therapy", "Refer for pulmonary endarterectomy", "Evaluate for lung transplantation"]'::jsonb, 2, 'Pulmonary hypertension due to left heart disease (group 2) is the most common form of pulmonary hypertension, and its treatment is optimization of the underlying left heart failure with guideline-directed medical therapy, diuretics, and volume control. Pulmonary arterial hypertension-specific vasodilators such as sildenafil and bosentan are not indicated in group 2 disease and may cause harm by increasing pulmonary blood flow into a failing left heart. Pulmonary endarterectomy is the treatment for chronic thromboembolic pulmonary hypertension, not left heart disease. Lung transplantation is a last resort for refractory disease, not first-line management.', 'Medium', 69, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 55-year-old man had a pulmonary embolism 2 years ago and has persistent exertional dyspnea despite therapeutic anticoagulation. Echocardiography shows a right ventricular systolic pressure of 60 mmHg, and chest CT shows webs and bands within the pulmonary arteries. Which of the following is the best next test?', '["Right heart catheterization", "High-resolution chest CT", "D-dimer level", "Ventilation-perfusion scan", "Cardiac MRI"]'::jsonb, 3, 'Chronic thromboembolic pulmonary hypertension should be suspected when pulmonary hypertension persists after acute pulmonary embolism, and the ventilation-perfusion scan is the screening test of choice because it is highly sensitive for mismatched perfusion defects. CT pulmonary angiography can miss distal chronic disease. Right heart catheterization confirms the diagnosis and measures hemodynamics but comes after a positive screening V/Q scan. A D-dimer is not useful in chronic disease. High-resolution CT evaluates parenchymal lung disease, and cardiac MRI assesses right ventricular function, but neither screens for chronic thromboembolic disease as well as V/Q scanning.', 'Hard', 70, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 68-year-old man has 2 years of progressive dyspnea on exertion and a chronic dry cough. He has bibasal inspiratory crackles and digital clubbing. High-resolution CT shows subpleural, basal-predominant honeycombing with traction bronchiectasis and minimal ground-glass opacity. Pulmonary function tests show a restrictive pattern with reduced DLCO. Which of the following is the most appropriate treatment?', '["Prednisone", "Nintedanib", "Methotrexate", "Azathioprine", "Inhaled bronchodilators"]'::jsonb, 1, 'The high-resolution CT shows a definite usual interstitial pneumonia pattern with subpleural basal honeycombing, which in this clinical context establishes idiopathic pulmonary fibrosis. Antifibrotic therapy with nintedanib or pirfenidone slows the decline in lung function and is the standard treatment. Corticosteroids and immunosuppressants such as prednisone, azathioprine, and methotrexate are ineffective and harmful in IPF; the PANTHER trial showed increased mortality with combination immunosuppression. Inhaled bronchodilators do not modify fibrosis or improve outcomes in IPF, and lung transplantation is considered only for selected patients with advanced disease.', 'Medium', 71, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 62-year-old woman with progressive dyspnea has pulmonary function tests showing forced vital capacity 62% of predicted, FEV1/FVC ratio 0.85, total lung capacity reduced, and DLCO 45% of predicted. Which of the following best describes this pattern?', '["Obstructive lung disease", "Asthma with air trapping", "Isolated pulmonary vascular disease", "Neuromuscular weakness", "Restrictive interstitial lung disease"]'::jsonb, 4, 'Reduced forced vital capacity and total lung capacity with a preserved or elevated FEV1/FVC ratio define a restrictive pattern, and a markedly reduced DLCO points to interstitial or alveolar-capillary disease rather than chest wall or neuromuscular causes. Obstructive disease and asthma lower the FEV1/FVC ratio and increase lung volumes, the opposite of this pattern. Isolated pulmonary vascular disease can reduce DLCO but does not reduce total lung capacity. Neuromuscular weakness reduces lung volumes but typically preserves DLCO because the alveolar-capillary membrane is intact.', 'Medium', 72, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 45-year-old woman with systemic sclerosis, tight skin over her hands and face, and Raynaud phenomenon has progressive dyspnea over 6 months. High-resolution CT shows bilateral ground-glass opacities with basal predominance and fine reticulation without honeycombing. Which of the following is the most likely interstitial pattern?', '["Nonspecific interstitial pneumonia", "Usual interstitial pneumonia", "Cryptogenic organizing pneumonia", "Desquamative interstitial pneumonia", "Lymphangioleiomyomatosis"]'::jsonb, 0, 'Interstitial lung disease in systemic sclerosis is most commonly nonspecific interstitial pneumonia, characterized by ground-glass opacity with basal predominance, fine reticulation, subpleural sparing, and absence of honeycombing. Usual interstitial pneumonia shows honeycombing with a basal subpleural distribution and is typical of idiopathic pulmonary fibrosis or rheumatoid arthritis, not scleroderma. Cryptogenic organizing pneumonia presents with patchy peribronchial consolidations rather than diffuse ground-glass change. Desquamative interstitial pneumonia is smoking-related with diffuse ground-glass opacity. Lymphangioleiomyomatosis affects women of childbearing age with thin-walled cysts and recurrent pneumothorax.', 'Hard', 73, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 35-year-old Black man has bilateral hilar lymphadenopathy found incidentally on a chest radiograph obtained for a pre-employment examination. He has no cough, dyspnea, fever, eye symptoms, or skin lesions. Pulmonary function tests and serum calcium are normal. Which of the following is the most appropriate next step?', '["Start prednisone", "Start methotrexate", "Observation with serial imaging and pulmonary function tests", "Start infliximab", "Transbronchial lung biopsy"]'::jsonb, 2, 'Asymptomatic stage I sarcoidosis with isolated bilateral hilar adenopathy frequently remits spontaneously, so observation with serial chest imaging and pulmonary function tests is appropriate. Treatment is reserved for symptomatic, progressive, or organ-threatening disease involving the eyes, heart, central nervous system, or calcium metabolism. Corticosteroids carry significant toxicity and do not improve long-term outcomes in asymptomatic disease. Methotrexate and infliximab are second- and third-line agents for refractory disease. Biopsy is unnecessary when the clinical and radiographic picture is classic for stage I sarcoidosis.', 'Medium', 74, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 28-year-old woman presents with fever, painful bilateral ankle swelling, and tender red nodules on her shins. Chest radiograph shows bilateral hilar lymphadenopathy. Which of the following is the most likely diagnosis and the most appropriate management?', '["Start high-dose prednisone immediately", "NSAIDs and observation for Lofgren syndrome", "Start methotrexate", "Bronchoscopy with biopsy", "Start infliximab"]'::jsonb, 1, 'This is Lofgren syndrome, the acute presentation of sarcoidosis characterized by erythema nodosum, bilateral hilar adenopathy, ankle arthritis, and fever, which carries an excellent prognosis with frequent spontaneous remission within months. NSAIDs for symptom control with observation are sufficient. High-dose prednisone is reserved for severe or persistent disease, such as ocular, cardiac, or neurologic involvement, and is not needed here. Methotrexate and infliximab are used for chronic refractory sarcoidosis, not acute Lofgren syndrome. Bronchoscopy with biopsy is unnecessary because the clinical triad is diagnostic.', 'Medium', 75, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 42-year-old man with known pulmonary sarcoidosis presents with syncope. ECG shows complete heart block, and echocardiography shows basal septal thinning with a reduced ejection fraction. Which of the following is the most appropriate next step in management?', '["Reassurance and outpatient follow-up", "Start a beta-blocker", "Pacemaker implantation alone", "Implantable cardioverter-defibrillator placement and corticosteroids", "Amiodarone alone"]'::jsonb, 3, 'Cardiac sarcoidosis with complete heart block carries a high risk of ventricular arrhythmias and sudden cardiac death, so an implantable cardioverter-defibrillator is preferred over a pacemaker alone, combined with corticosteroids to suppress granulomatous inflammation. A pacemaker treats bradycardia but does not protect against ventricular tachycardia or fibrillation, which are common in cardiac sarcoidosis. Beta-blockers worsen atrioventricular block and are contraindicated. Amiodarone alone does not prevent sudden death and is at most an adjunct. Reassurance is dangerous because cardiac sarcoidosis is a leading cause of death in sarcoidosis.', 'Hard', 76, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 50-year-old dairy farmer has recurrent episodes of fever, chills, and dyspnea that begin 4 to 6 hours after working in a barn with moldy hay and resolve over weekends away from the farm. Examination shows inspiratory crackles, and chest radiograph shows diffuse ground-glass opacities. Which of the following is the most likely diagnosis and management?', '["Hypersensitivity pneumonitis; avoid antigen exposure and give corticosteroids", "Idiopathic pulmonary fibrosis; start nintedanib", "Asthma; start inhaled corticosteroids", "Bacterial pneumonia; start antibiotics", "Sarcoidosis; start prednisone"]'::jsonb, 0, 'Hypersensitivity pneumonitis, here farmer''s lung from inhaled moldy hay antigens, is an immune-mediated alveolitis with symptoms hours after exposure and improvement away from the source. The cornerstone of treatment is avoidance of the offending antigen, with corticosteroids for acute or severe disease. Idiopathic pulmonary fibrosis is chronic and progressive without an exposure pattern and does not improve on weekends. Asthma is obstructive with wheeze and reversibility, not ground-glass alveolitis. Bacterial pneumonia causes lobar consolidation and does not recur with exposure. Sarcoidosis typically shows hilar adenopathy, not this exposure-related pattern.', 'Medium', 77, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 65-year-old retired shipyard worker with 30 years of asbestos exposure has progressive dyspnea on exertion. Chest radiograph shows bilateral pleural plaques and lower-lobe reticular opacities with volume loss. Which of the following is the most likely diagnosis?', '["Silicosis", "Coal worker''s pneumoconiosis", "Berylliosis", "Hypersensitivity pneumonitis", "Asbestosis"]'::jsonb, 4, 'Asbestosis is pulmonary fibrosis caused by asbestos exposure, characteristically with bilateral pleural plaques and lower-lobe reticular fibrosis after a long latency of 20 to 30 years, matching this shipyard worker''s history and imaging. Silicosis affects the upper lobes with small rounded opacities and eggshell hilar calcifications in miners and sandblasters. Coal worker''s pneumoconiosis also favors the upper lobes with small rounded opacities. Berylliosis mimics sarcoidosis with hilar adenopathy and noncaseating granulomas. Hypersensitivity pneumonitis is caused by inhaled organic antigens with ground-glass change and an exposure-related symptom pattern, not pleural plaques.', 'Medium', 78, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 55-year-old sandblaster has chronic cough and dyspnea. Chest radiograph shows upper-lobe small rounded opacities with eggshell calcification of the hilar lymph nodes. He is at markedly increased risk for which of the following?', '["Mesothelioma", "Tuberculosis", "Lung adenocarcinoma only", "Pulmonary embolism", "Asthma"]'::jsonb, 1, 'This is silicosis from silica dust exposure in sandblasting, with upper-lobe nodules and eggshell hilar calcifications. Silica impairs alveolar macrophage function, markedly increasing the risk of tuberculosis, known as silicotuberculosis, which must be actively screened for with sputum studies and chest imaging. Progressive massive fibrosis can develop with continued exposure. Lung cancer risk is also increased in silicosis, but tuberculosis is the classic and most important associated infection. Mesothelioma is associated with asbestos, not silica. Pulmonary embolism and asthma are not associated with silicosis.', 'Medium', 79, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 74-year-old man with heart failure has bilateral pleural effusions. Thoracentesis of the right effusion shows pleural protein 1.8 g/dL with serum protein 6.5 g/dL, pleural LDH 90 U/L with serum LDH 200 U/L, and pleural pH 7.45. By Light criteria this effusion is best classified as which of the following, and what is the most appropriate management?', '["Exudate; chest tube drainage", "Exudate; pleural biopsy", "Transudate; diuretics for heart failure", "Transudate; repeat thoracentesis", "Exudate; antibiotics"]'::jsonb, 2, 'By Light criteria this is a transudate: the pleural-to-serum protein ratio is 0.28 (below 0.5), the pleural-to-serum LDH ratio is 0.45 (below 0.6), and pleural LDH is below two-thirds of the serum upper limit. A transudate in a patient with heart failure is caused by increased hydrostatic pressure and is treated by managing the underlying heart failure with diuretics, not by draining the chest. Chest tube drainage, pleural biopsy, and antibiotics are indicated for exudative or infected effusions. Repeat thoracentesis is unnecessary once the transudative nature is established.', 'Medium', 80, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 58-year-old man with lobar pneumonia has a left pleural effusion. Thoracentesis shows pH 7.10, glucose 35 mg/dL, LDH 1200 U/L, and a positive Gram stain. Which of the following is the most appropriate next step?', '["Observation", "Repeat thoracentesis in one week", "Intravenous antibiotics alone", "Chest tube drainage plus antibiotics", "Pleurodesis"]'::jsonb, 3, 'This is a complicated parapneumonic effusion or empyema: pleural pH below 7.20, low glucose, very high LDH, and a positive Gram stain indicate infected, loculated fluid that requires chest tube drainage in addition to antibiotics. Antibiotics alone cannot sterilize undrained infected pleural fluid because penetration into loculated collections is poor. Observation or repeating thoracentesis in a week delays source control and risks progression to a fibrous pleural peel with trapped lung. Pleurodesis is used for recurrent malignant effusions to prevent reaccumulation, not for acute infected effusions, and fibrinolytics or surgery are considered if drainage fails.', 'Medium', 81, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 40-year-old man has 3 weeks of fever, night sweats, and weight loss with a unilateral pleural effusion. Thoracentesis shows a lymphocyte-predominant exudate with pleural adenosine deaminase of 65 U/L and no malignant cells on cytology. Which of the following is the most likely diagnosis?', '["Tuberculous pleuritis", "Malignant pleural effusion", "Parapneumonic effusion", "Pulmonary embolism", "Rheumatoid pleuritis"]'::jsonb, 0, 'A lymphocyte-predominant exudate with adenosine deaminase above 40 U/L in a young patient with constitutional symptoms is classic for tuberculous pleuritis, which is a hypersensitivity reaction to mycobacterial antigens in the pleural space. A malignant effusion usually has positive cytology and a lower adenosine deaminase. A parapneumonic effusion is neutrophil-predominant and associated with acute pneumonia. Pulmonary embolism causes small, often bloody effusions with low adenosine deaminase. Rheumatoid pleuritis has very low glucose and low pH with a different clinical picture.', 'Medium', 82, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 60-year-old woman develops a milky pleural effusion after esophagectomy. Pleural fluid analysis shows triglycerides 180 mg/dL and cholesterol 45 mg/dL. Which of the following is the most likely diagnosis?', '["Empyema", "Hemothorax", "Transudate from heart failure", "Malignant pleural effusion", "Chylothorax"]'::jsonb, 4, 'Milky pleural fluid with triglycerides above 110 mg/dL establishes chylothorax, here caused by thoracic duct injury during esophagectomy, with chyle leaking into the pleural space. Empyema is purulent infected fluid with a positive Gram stain, not milky chyle. Hemothorax is bloody with a pleural hematocrit greater than 50% of blood. A transudate from heart failure is clear, straw-colored fluid with low protein and LDH. A malignant effusion is usually serosanguineous with positive cytology and does not have markedly elevated triglycerides.', 'Medium', 83, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 22-year-old tall, thin man presents with sudden right-sided pleuritic chest pain and mild dyspnea. His vital signs are stable, oxygen saturation is 97% on room air, and chest radiograph shows a small right apical pneumothorax with a rim of less than 2 cm and no mediastinal shift. Which of the following is the most appropriate management?', '["Immediate chest tube placement", "Needle decompression", "Observation with supplemental oxygen and repeat imaging", "Pleurodesis", "Endotracheal intubation"]'::jsonb, 2, 'A small primary spontaneous pneumothorax in a hemodynamically stable patient can be managed with observation and supplemental oxygen, which increases the rate of pleural air reabsorption approximately fourfold, along with repeat imaging to confirm resolution. A chest tube is indicated for large, symptomatic, or unstable pneumothoraces. Needle decompression is the emergency treatment for tension pneumothorax, which is absent here. Pleurodesis is used to prevent recurrence after a first episode in selected patients, not as initial therapy. Intubation is not indicated in a stable patient breathing comfortably.', 'Easy', 84, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 45-year-old man presents with severe dyspnea, hypotension, absent breath sounds on the left, trachea deviated to the right, and distended neck veins. Which of the following is the immediate next step in management?', '["Chest radiograph", "Endotracheal intubation and mechanical ventilation", "Needle decompression followed by chest tube placement", "Intravenous fluids alone", "High-flow oxygen and observation"]'::jsonb, 2, 'This is a tension pneumothorax, a clinical diagnosis in which air enters the pleural space but cannot escape, collapsing the lung and shifting the mediastinum with obstructive shock. Immediate needle decompression at the second intercostal space in the midclavicular line is life-saving, followed by definitive chest tube placement. Waiting for a chest radiograph delays treatment and can be fatal. Intubation with positive-pressure ventilation worsens tension before decompression. Fluids and oxygen alone do not relieve the trapped air causing the shock.', 'Easy', 85, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 68-year-old man with severe COPD presents with sudden worsening dyspnea and chest pain. Chest radiograph shows a large right pneumothorax with near-complete lung collapse. Which of the following is the most appropriate management?', '["Observation", "Needle aspiration alone", "Supplemental oxygen alone", "Chest tube thoracostomy", "Bronchoscopy"]'::jsonb, 3, 'This is a secondary spontaneous pneumothorax occurring in a patient with underlying lung disease and a large collapse, which requires chest tube thoracostomy. Patients with COPD have poor respiratory reserve and their pneumothoraces rarely re-expand with observation or needle aspiration alone, and tension physiology can develop quickly. Needle aspiration is an option for primary spontaneous pneumothorax in stable patients without lung disease, not for secondary pneumothorax. Supplemental oxygen alone is insufficient for a large pneumothorax with near-complete collapse. Bronchoscopy does not treat pneumothorax and is not indicated here.', 'Medium', 86, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 70-year-old man with 40 years of asbestos exposure in construction has progressive dyspnea and chest pain. CT of the chest shows diffuse nodular pleural thickening encasing the lung with a moderate pleural effusion. Which of the following is the best next step?', '["CT-guided pleural biopsy", "Repeat chest radiograph in 6 months", "Start chemotherapy empirically", "Pleurodesis", "Thoracentesis with cytology alone"]'::jsonb, 0, 'Suspected malignant pleural mesothelioma requires tissue diagnosis, and CT-guided or thoracoscopic pleural biopsy is the best next step because it provides adequate tissue for histology and immunohistochemistry. Pleural fluid cytology alone has low sensitivity for mesothelioma, around 30 percent, because the tumor sheds few diagnostic cells. Surveillance imaging delays diagnosis of an aggressive malignancy. Empiric chemotherapy without histologic confirmation is inappropriate. Pleurodesis is a palliative procedure for recurrent effusions after diagnosis, not a diagnostic step, and staging with CT or PET follows tissue confirmation.', 'Medium', 87, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A pleural biopsy shows malignant epithelioid cells. Which of the following immunohistochemical profiles supports malignant mesothelioma over lung adenocarcinoma?', '["TTF-1 positive and napsin A positive", "Carcinoembryonic antigen positive", "Ber-EP4 positive", "p40 positive", "Calretinin and WT-1 positive"]'::jsonb, 4, 'Calretinin and WT-1 are positive in malignant mesothelioma, along with CK5/6 and D2-40, whereas lung adenocarcinoma is positive for TTF-1, napsin A, carcinoembryonic antigen, and Ber-EP4. This immunohistochemical panel distinguishes mesothelioma from metastatic adenocarcinoma involving the pleura, and a panel approach is used because no single marker is perfectly specific or sensitive on its own. TTF-1 and napsin A positivity favors adenocarcinoma, not mesothelioma. Carcinoembryonic antigen and Ber-EP4 are adenocarcinoma markers. p40 positivity favors squamous cell carcinoma, not mesothelioma, and electron microscopy can help in difficult cases.', 'Hard', 88, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 65-year-old man has unresectable epithelioid malignant pleural mesothelioma with ECOG performance status 1 and good organ function. Which of the following is the most appropriate systemic therapy?', '["Observation", "Cisplatin plus pemetrexed", "Erlotinib", "High-dose corticosteroids", "Single-agent doxorubicin"]'::jsonb, 1, 'First-line systemic therapy for unresectable malignant pleural mesothelioma is a platinum agent plus pemetrexed, most commonly cisplatin with pemetrexed, which improves survival compared with cisplatin alone; immunotherapy with nivolumab plus ipilimumab is an alternative first-line option, and bevacizumab can be added to chemotherapy. Erlotinib, an EGFR inhibitor, is ineffective in mesothelioma because the tumor is not EGFR-driven. High-dose corticosteroids do not treat mesothelioma. Single-agent doxorubicin has a low response rate and is not standard first-line therapy. Observation misses the window for effective treatment in a fit patient.', 'Hard', 89, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 62-year-old woman is 2 weeks after total knee replacement when she develops mild dyspnea. CT pulmonary angiography shows an isolated subsegmental pulmonary embolus. Lower extremity ultrasound shows no proximal deep vein thrombosis, there is no right ventricular strain, and her bleeding risk is low. Which of the following is the most appropriate management?', '["No treatment; discharge home", "Inferior vena cava filter", "Systemic thrombolysis", "Anticoagulation", "Repeat CT pulmonary angiography in 3 months"]'::jsonb, 3, 'Although truly incidental, asymptomatic subsegmental pulmonary embolism without deep vein thrombosis may be managed with surveillance, this patient is symptomatic with a recent major provoking factor and ongoing recurrence risk after orthopedic surgery, so anticoagulation is appropriate given her low bleeding risk. No treatment would leave a symptomatic patient with a provoked clot unprotected. An inferior vena cava filter does not treat pulmonary embolism and is used only when anticoagulation is contraindicated. Thrombolysis is reserved for massive embolism with shock. Repeat imaging does not guide therapy.', 'Hard', 90, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 58-year-old man is intubated in the ICU for sepsis-related pneumonia. On day 2 he meets criteria for moderate ARDS with a PaO2/FiO2 ratio of 180 on PEEP of 8 cm H2O, bilateral infiltrates on chest X-ray, and no evidence of cardiac failure. His current tidal volume is 10 mL/kg of predicted body weight. Which of the following is the most appropriate ventilator strategy?', '["Increase tidal volume to 12 mL/kg to improve oxygenation", "Initiate prone positioning as the first ventilator intervention", "Reduce tidal volume to 6 mL/kg of predicted body weight", "Increase PEEP to 20 cm H2O while keeping tidal volume at 10 mL/kg", "Allow permissive hypercapnia without changing tidal volume"]'::jsonb, 2, 'Lung-protective ventilation with low tidal volumes of 4-8 mL/kg of predicted body weight (typically 6 mL/kg) is the cornerstone of ARDS management and the only ventilator strategy proven to reduce mortality (ARDSNet). High tidal volumes cause volutrauma and worsen lung injury, so increasing to 12 mL/kg (A) is harmful. Prone positioning (B) is an adjunct for severe ARDS (PaO2/FiO2 <150), not the first step in moderate disease. Raising PEEP alone (D) without reducing tidal volume does not address volutrauma and may cause barotrauma. Permissive hypercapnia (E) is a consequence of low-volume ventilation, not a strategy on its own - the tidal volume must still be reduced.', 'Medium', 91, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 45-year-old woman develops acute dyspnea 4 days after an episode of severe acute pancreatitis. Her PaO2/FiO2 ratio is 220 on PEEP of 5 cm H2O. Chest X-ray shows bilateral opacities, and echocardiography shows normal left ventricular function with no evidence of volume overload. Which of the following findings best supports a diagnosis of ARDS?', '["Bilateral opacities with hypoxemia developing within 1 week of a known insult, not fully explained by cardiac failure", "Unilateral lobar consolidation with fever and productive cough", "PaO2/FiO2 ratio of 320 with bilateral pleural effusions", "Acute dyspnea with elevated BNP and Kerley B lines on chest X-ray", "Bilateral infiltrates that resolve within 24 hours of diuresis"]'::jsonb, 0, 'The Berlin definition of ARDS requires acute onset within 1 week of a known clinical insult, bilateral opacities not fully explained by effusions, lobar collapse, or nodules, hypoxemia with PaO2/FiO2 of 300 or less on PEEP of at least 5 cm H2O, and respiratory failure not fully explained by cardiac failure or fluid overload (A). A unilateral lobar consolidation (B) suggests pneumonia rather than ARDS. A PaO2/FiO2 ratio of 320 (C) does not meet the hypoxemia threshold for ARDS. Elevated BNP with Kerley B lines (D) points to cardiogenic pulmonary edema. Infiltrates that clear rapidly with diuresis (E) indicate hydrostatic edema rather than the permeability edema of ARDS.', 'Easy', 92, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 62-year-old man with severe ARDS from influenza pneumonia is on low tidal volume ventilation with PEEP of 14 cm H2O and FiO2 of 1.0. Despite this, his PaO2/FiO2 ratio is 85, and he remains severely hypoxemic. His plateau pressure is 28 cm H2O. Which of the following is the most appropriate next step in management?', '["Increase tidal volume to 10 mL/kg of predicted body weight", "Start inhaled nitric oxide as first-line therapy", "Initiate veno-venous ECMO immediately", "Place the patient in the prone position for at least 12 hours per day", "Switch to high-frequency oscillatory ventilation"]'::jsonb, 3, 'Prone positioning for at least 12 hours per day improves oxygenation and reduces mortality in severe ARDS (PaO2/FiO2 <150) by recruiting dorsal lung regions and improving ventilation-perfusion matching, making it the correct next step (D). Increasing tidal volume (A) causes volutrauma and worsens lung injury. Inhaled nitric oxide (B) transiently improves oxygenation but has no mortality benefit and is a rescue therapy, not first-line. ECMO (C) is reserved for refractory hypoxemia after proning and other rescue measures have failed. High-frequency oscillatory ventilation (E) is not recommended, as trials showed no benefit and possible harm.', 'Hard', 93, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 72-year-old man with severe COPD presents with increased dyspnea, productive cough, and drowsiness over 2 days. His arterial blood gas shows pH 7.28, PaCO2 68 mmHg, PaO2 55 mmHg, and HCO3 30 mEq/L. He is alert enough to cooperate and protect his airway. Which of the following is the most appropriate initial management?', '["Administer 100% oxygen by nonrebreather mask", "Initiate bilevel positive airway pressure (BiPAP)", "Proceed immediately to endotracheal intubation", "Give intravenous antibiotics alone and observe", "Start high-flow nasal cannula oxygen"]'::jsonb, 1, 'Noninvasive positive pressure ventilation with BiPAP is first-line for acute hypercapnic respiratory failure in COPD with acidosis (pH <7.35), as it unloads the respiratory muscles, improves ventilation, and reduces the need for intubation and mortality (B). High-flow 100% oxygen (A) worsens hypercapnia in COPD by blunting hypoxic drive and worsening ventilation-perfusion mismatch. Immediate intubation (C) is reserved for patients who fail NIV, cannot protect the airway, or have contraindications. Antibiotics alone (D) do not address the ventilatory failure. High-flow nasal cannula (E) is primarily for hypoxemic failure and is less effective than BiPAP for hypercapnia.', 'Medium', 94, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 34-year-old man with severe community-acquired pneumonia is on a 15 L nonrebreather mask with SpO2 84%, respiratory rate 34/min, and visible accessory muscle use. He is becoming drowsy and his work of breathing is increasing despite maximal supplemental oxygen. Arterial blood gas shows PaO2 52 mmHg with normal PaCO2. Which of the following is the most appropriate next step?', '["Trial of high-flow nasal cannula oxygen", "Initiate bilevel positive airway pressure (BiPAP)", "Increase oxygen to 100% via nonrebreather mask", "Administer nebulized bronchodilators and observe", "Proceed to endotracheal intubation and mechanical ventilation"]'::jsonb, 4, 'This patient has severe refractory hypoxemic respiratory failure with increasing work of breathing and altered mental status - signs of impending respiratory arrest - so definitive airway control with endotracheal intubation is the most appropriate next step (E). High-flow nasal cannula (A) is a bridge, not definitive therapy, in a tiring, hypoxic patient. BiPAP (B) is not first-line for hypoxemic failure without hypercapnia and delays intubation. He is already on maximal nonrebreather oxygen (C), so more oxygen will not help. Bronchodilators (D) do not treat the underlying pneumonia or hypoxemia.', 'Medium', 95, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 60-year-old man with a BMI of 42 kg/m2 presents with progressive daytime sleepiness, morning headaches, and dyspnea on exertion. He has no history of COPD or smoking. Arterial blood gas shows pH 7.36, PaCO2 55 mmHg, PaO2 62 mmHg, and HCO3 32 mEq/L. Pulmonary function tests show a mild restrictive pattern. Which of the following is the most likely cause of his hypercapnic respiratory failure?', '["Acute COPD exacerbation", "Opioid overdose", "Obesity hypoventilation syndrome", "Myasthenia gravis", "Central sleep apnea"]'::jsonb, 2, 'Obesity hypoventilation syndrome is defined by obesity (BMI 30 or higher) with chronic daytime hypercapnia (PaCO2 >45 mmHg) in the absence of another cause, with a compensated respiratory acidosis - elevated bicarbonate with near-normal pH, as seen here (C). COPD exacerbation (A) is unlikely without smoking history or obstructive pulmonary function tests. Opioid overdose (B) causes acute hypercapnia with a low pH, not a chronic compensated picture. Myasthenia gravis (D) causes weakness and acute ventilatory failure, not chronic compensated hypercapnia. Central sleep apnea (E) causes sleep-disordered breathing but does not produce sustained daytime hypercapnia with elevated bicarbonate.', 'Medium', 96, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 65-year-old woman intubated for pneumonia is improving on day 3. She is on FiO2 0.4, PEEP 5 cm H2O, and is hemodynamically stable with minimal secretions. During a spontaneous breathing trial on pressure support, her respiratory rate is 22/min, tidal volume 450 mL, and SpO2 96%. Her rapid shallow breathing index (RSBI) is 78. Which of the following is the most appropriate next step?', '["Proceed with extubation", "Continue full ventilatory support for another 48 hours", "Perform a tracheostomy", "Switch to synchronized intermittent mandatory ventilation", "Increase PEEP to 10 cm H2O"]'::jsonb, 0, 'A successful spontaneous breathing trial with an RSBI below 105 (here 78) predicts successful extubation, so proceeding with extubation is appropriate (A). Continuing full support (B) unnecessarily prolongs ventilation and increases the risk of ventilator-associated pneumonia and deconditioning. Tracheostomy (C) is reserved for prolonged ventilation, typically after 10-14 days. Switching to SIMV (D) is a weaning mode, not a next step after a passed breathing trial. Increasing PEEP (E) is unnecessary in a patient who is already oxygenating well on minimal support.', 'Medium', 97, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 55-year-old man intubated for ARDS suddenly develops hypotension (BP 80/50 mmHg), tachycardia, and rising peak inspiratory pressures. Examination shows absent breath sounds on the right side of the chest and tracheal deviation to the left. His oxygen saturation is falling rapidly. Which of the following is the most appropriate immediate management?', '["Increase PEEP to recruit the collapsed lung", "Perform needle decompression followed by chest tube placement", "Administer intravenous fluids and vasopressors only", "Perform urgent bronchoscopy", "Suction the endotracheal tube"]'::jsonb, 1, 'This is a tension pneumothorax - a life-threatening ventilator complication presenting with hypotension, absent breath sounds, tracheal deviation, and rising airway pressures. Immediate needle decompression in the second intercostal space followed by definitive chest tube placement relieves the trapped air and restores venous return (B). Increasing PEEP (A) worsens the pneumothorax by forcing more air into the pleural space. Fluids and pressors alone (C) do not address the mechanical cause. Bronchoscopy (D) is not indicated for pneumothorax. Suctioning the tube (E) addresses mucus plugging, not the absent breath sounds and tracheal deviation seen here.', 'Medium', 98, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 50-year-old woman with ARDS is on volume-controlled ventilation with a tidal volume of 6 mL/kg of predicted body weight. Her plateau pressure is measured at 34 cm H2O, and her peak pressure is 40 cm H2O. Her oxygenation is adequate on FiO2 0.6. Which of the following is the most appropriate ventilator adjustment?', '["Increase tidal volume to 8 mL/kg", "Increase PEEP to 20 cm H2O", "Switch to pressure-controlled ventilation without changing tidal volume", "Reduce tidal volume to 4 mL/kg of predicted body weight", "Administer neuromuscular blockade as the first intervention"]'::jsonb, 3, 'Plateau pressure reflects alveolar pressure, and keeping it below 30 cm H2O is a key goal of lung-protective ventilation; a plateau of 34 cm H2O requires reducing tidal volume further, to 4 mL/kg if needed (D). Increasing tidal volume (A) would raise plateau pressure further and worsen lung injury. Raising PEEP (B) increases mean airway pressure without addressing the high plateau. Switching modes without changing tidal volume (C) does not reduce the delivered volume or plateau pressure. Neuromuscular blockade (E) can improve oxygenation in severe ARDS but does not correct an elevated plateau pressure.', 'Hard', 99, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 40-year-old man presents with confusion and rapid, deep breathing. Laboratory studies show sodium 140 mEq/L, chloride 108 mEq/L, bicarbonate 15 mEq/L, and glucose 110 mg/dL. Arterial blood gas shows pH 7.31 and PaCO2 30 mmHg. Which of the following best describes his acid-base status?', '["High anion gap metabolic acidosis with appropriate respiratory compensation", "Respiratory acidosis with metabolic compensation", "Normal anion gap metabolic acidosis", "Mixed metabolic acidosis and respiratory alkalosis", "Metabolic alkalosis"]'::jsonb, 0, 'The anion gap is 140 - (108 + 15) = 17, which is elevated, indicating a high anion gap metabolic acidosis (A). Winter''s formula predicts the expected PaCO2 as 1.5 x 15 + 8 +/- 2 = 28.5-32.5 mmHg, and the actual PaCO2 of 30 mmHg falls within this range, confirming appropriate respiratory compensation. A primary respiratory acidosis (B) would show an elevated PaCO2 with a low pH, not a low PaCO2. A normal anion gap acidosis (C) would have an anion gap of 8-12. A mixed disorder (D) would show a PaCO2 outside the Winter''s range. Metabolic alkalosis (E) is excluded by the low pH and low bicarbonate.', 'Hard', 100, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 55-year-old woman with a history of prolonged vomiting presents with weakness and muscle cramps. Laboratory studies show potassium 3.0 mEq/L, chloride 92 mEq/L, and bicarbonate 34 mEq/L. Arterial blood gas shows pH 7.48 and PaCO2 46 mmHg. Which of the following best describes her acid-base status?', '["Respiratory alkalosis", "Metabolic acidosis", "Respiratory acidosis", "Mixed metabolic and respiratory acidosis", "Metabolic alkalosis with appropriate respiratory compensation"]'::jsonb, 4, 'The elevated pH (7.48) with a high bicarbonate (34 mEq/L) indicates a primary metabolic alkalosis, classically from vomiting with loss of gastric acid and volume contraction, often accompanied by hypokalemia and hypochloremia (E). The expected compensatory PaCO2 is 0.7 x 34 + 20 +/- 5 = 39-49 mmHg, and the actual value of 46 mmHg confirms appropriate respiratory compensation. A primary respiratory alkalosis (A) would show a low PaCO2 with a low or normal bicarbonate. Metabolic acidosis (B) would show a low pH and low bicarbonate. Respiratory acidosis (C) would show a low pH with elevated PaCO2. A mixed acidosis (D) is inconsistent with the alkaline pH.', 'Medium', 101, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 30-year-old man is brought to the emergency department with acute dyspnea and confusion after a large opioid ingestion. He is breathing shallowly at 8 breaths per minute. Arterial blood gas shows pH 7.24, PaCO2 60 mmHg, and HCO3 26 mEq/L. He has no prior lung disease. Which of the following best describes his acid-base status?', '["Chronic respiratory acidosis with metabolic compensation", "Acute respiratory acidosis", "Metabolic acidosis", "Respiratory alkalosis", "Mixed respiratory acidosis and metabolic alkalosis"]'::jsonb, 1, 'The low pH with a markedly elevated PaCO2 indicates a primary respiratory acidosis from hypoventilation due to opioid-induced respiratory depression (B). In acute respiratory acidosis, bicarbonate rises only about 1 mEq/L for every 10 mmHg rise in PaCO2, so a bicarbonate of 26 mEq/L fits an acute process. A chronic respiratory acidosis (A) would show a much higher bicarbonate (about 3.5 mEq/L per 10 mmHg rise in PaCO2) after renal compensation over days. A primary metabolic acidosis (C) would show a low bicarbonate. Respiratory alkalosis (D) would show a high pH with low PaCO2. There is no evidence of a concurrent metabolic alkalosis (E).', 'Medium', 102, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 68-year-old man with a 45 pack-year smoking history undergoes pulmonary function testing for progressive dyspnea. Results show FEV1/FVC ratio of 0.62, FEV1 55% of predicted, total lung capacity 110% of predicted, and DLCO 60% of predicted. Which of the following best describes his pulmonary function pattern?', '["Restrictive ventilatory defect", "Normal pulmonary function", "Obstructive ventilatory defect with emphysema", "Isolated reduction in DLCO due to anemia", "Mixed obstructive and restrictive defect"]'::jsonb, 2, 'An FEV1/FVC ratio below 0.70 defines airflow obstruction, and an FEV1 of 55% indicates moderate-to-severe obstruction (C). The increased total lung capacity reflects hyperinflation from air trapping, and the reduced DLCO indicates loss of alveolar-capillary surface area from emphysema. A restrictive defect (A) would show a normal or high FEV1/FVC ratio with a reduced total lung capacity. The results are clearly abnormal, excluding normal function (B). An isolated DLCO reduction (D) would occur with normal spirometry, as in anemia. A mixed defect (E) requires both obstruction and a reduced total lung capacity, which is not present here.', 'Hard', 103, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 58-year-old woman with progressive dyspnea and dry cough undergoes pulmonary function testing. Results show FEV1/FVC ratio of 0.88, FVC 58% of predicted, total lung capacity 62% of predicted, and DLCO 55% of predicted. High-resolution CT shows bilateral basal reticular opacities with honeycombing. Which of the following best describes her pulmonary function pattern?', '["Restrictive ventilatory defect consistent with interstitial lung disease", "Obstructive ventilatory defect", "Normal spirometry", "Asthma with reversible obstruction", "Restrictive defect due to neuromuscular weakness"]'::jsonb, 0, 'A preserved or elevated FEV1/FVC ratio with a reduced FVC and a reduced total lung capacity defines a restrictive defect, and the reduced DLCO with basal reticular opacities and honeycombing points to interstitial lung disease with impaired gas exchange (A). An obstructive defect (B) would show a low FEV1/FVC ratio. The markedly reduced FVC and TLC exclude normal spirometry (C). Asthma (D) causes reversible airflow obstruction with a low FEV1/FVC ratio, not restriction. Neuromuscular weakness (E) can cause a restrictive pattern, but the DLCO is typically normal because the lung parenchyma is intact, unlike here.', 'Medium', 104, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 28-year-old woman with episodic wheezing and nocturnal cough undergoes spirometry. Her FEV1/FVC ratio is 0.65 and FEV1 is 78% of predicted. After inhaled albuterol, her FEV1 increases by 15% and 250 mL. Total lung capacity and DLCO are normal. Which of the following is the most likely diagnosis?', '["COPD with fixed airflow obstruction", "Restrictive lung disease", "Normal spirometry", "Asthma with reversible airflow obstruction", "Bronchiectasis"]'::jsonb, 3, 'A significant bronchodilator response - an increase in FEV1 of at least 12% and 200 mL - demonstrates reversible airflow obstruction, the hallmark of asthma (D). COPD (A) is characterized by fixed, largely irreversible obstruction, and is uncommon in a 28-year-old nonsmoker. A restrictive pattern (B) would show a reduced total lung capacity with a preserved FEV1/FVC ratio. The low FEV1/FVC ratio excludes normal spirometry (C). Bronchiectasis (E) causes chronic productive cough with fixed obstruction and often bronchial wall thickening on imaging, not a reversible pattern with normal DLCO.', 'Medium', 105, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 52-year-old man with a BMI of 38 kg/m2 reports loud snoring, witnessed apneas, morning headaches, and excessive daytime sleepiness. His wife reports he stops breathing during sleep. A sleep study shows an apnea-hypopnea index (AHI) of 32 events per hour with oxygen desaturation to 82%. Which of the following is the most appropriate treatment?', '["Supplemental oxygen alone at night", "Continuous positive airway pressure (CPAP)", "Modafinil alone", "Uvulopalatopharyngoplasty as first-line therapy", "Weight loss alone"]'::jsonb, 1, 'An AHI of 30 or more indicates severe obstructive sleep apnea, and continuous positive airway pressure is the first-line treatment, as it splints the upper airway open, eliminates apneas, and improves daytime sleepiness and cardiovascular outcomes (B). Supplemental oxygen alone (A) corrects desaturation but does not prevent airway collapse or apneas. Modafinil (C) treats residual sleepiness but not the underlying obstruction. Surgery such as uvulopalatopharyngoplasty (D) is reserved for selected patients who cannot tolerate CPAP. Weight loss (E) is recommended as an adjunct but is not sufficient alone for severe OSA.', 'Easy', 106, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 48-year-old woman with a BMI of 44 kg/m2 presents with daytime somnolence, morning headaches, and dyspnea. She is hypercapnic while awake, with PaCO2 52 mmHg, and a sleep study shows an AHI of 28 events per hour. She has no history of COPD. Examination shows signs of cor pulmonale. Which of the following is the most appropriate initial therapy?', '["Continuous positive airway pressure (CPAP) alone", "Supplemental oxygen alone", "Bariatric surgery as initial therapy", "Diuretics alone", "Nocturnal bilevel positive airway pressure (BiPAP)"]'::jsonb, 4, 'This patient has obesity hypoventilation syndrome - obesity with chronic daytime hypercapnia - and nocturnal bilevel positive airway pressure is the preferred initial therapy because it provides ventilatory support that corrects both the obstructive events and the awake hypoventilation (E). CPAP alone (A) treats the obstructive apneas but is less effective for sustained daytime hypercapnia. Supplemental oxygen alone (B) can worsen hypercapnia and does not address hypoventilation. Bariatric surgery (C) is a long-term option but not initial therapy for symptomatic hypoventilation. Diuretics (D) may relieve right heart failure symptoms but do not treat the underlying ventilatory failure.', 'Hard', 107, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 60-year-old man has hypertension that remains uncontrolled on three antihypertensive agents, including a diuretic. His BMI is 34 kg/m2, and he reports loud snoring, nocturia, and unrefreshing sleep. He has no renal artery bruit. Which of the following is the most appropriate next step in his evaluation?', '["Add a fourth antihypertensive agent", "Order renal artery Doppler ultrasonography", "Order polysomnography (sleep study)", "Measure 24-hour urine cortisol", "Obtain CT of the adrenal glands"]'::jsonb, 2, 'Obstructive sleep apnea is a common and treatable cause of resistant hypertension, and this patient''s obesity, snoring, nocturia, and unrefreshing sleep make it the most likely secondary cause, so polysomnography is the appropriate next step (C). Adding a fourth agent (A) without identifying the underlying cause leaves the apnea untreated. Renal artery Doppler (B) evaluates renovascular hypertension, which is less likely without a bruit or suggestive features. A 24-hour urine cortisol (D) screens for Cushing syndrome, which typically presents with weight gain, striae, and other features not described here. Adrenal CT (E) evaluates for pheochromocytoma or aldosteronoma, which are less likely than OSA in this patient.', 'Medium', 108, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 45-year-old man with bronchiectasis presents with coughing up approximately 400 mL of blood over 2 hours. His oxygen saturation is 88% on room air, and he is coughing continuously. Chest X-ray shows right lower lobe bronchiectasis with an air-fluid level. Which of the following is the most appropriate immediate management?', '["Position the patient with the bleeding lung dependent and secure the airway", "Start intravenous antibiotics alone and observe", "Administer high-dose intravenous corticosteroids", "Proceed immediately to surgical lobectomy", "Give nebulized tranexamic acid alone"]'::jsonb, 0, 'Massive hemoptysis is life-threatening primarily because of asphyxiation, not blood loss, so the immediate priority is protecting the airway and positioning the patient with the bleeding lung dependent to prevent blood from flooding the healthy lung (A). Antibiotics alone (B) do not address the immediate airway threat. Corticosteroids (C) have no role in acute hemoptysis. Emergency lobectomy (D) carries high mortality and is reserved for cases where bronchial artery embolization fails or is unavailable. Nebulized tranexamic acid (E) may be an adjunct but is not a substitute for airway protection and definitive localization of bleeding.', 'Medium', 109, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 65-year-old man with a 40 pack-year smoking history presents with hemoptysis for 2 weeks and unintentional weight loss of 5 kg. Chest X-ray shows a right upper lobe mass. He is hemodynamically stable with an oxygen saturation of 96% on room air. Which of the following is the most appropriate next step in his evaluation?', '["Sputum acid-fast bacilli testing only", "Bronchoscopy as the first diagnostic test", "Start empiric antibiotics", "Obtain CT of the chest with contrast", "Repeat chest X-ray in 6 weeks"]'::jsonb, 3, 'In a heavy smoker with hemoptysis, weight loss, and a lung mass, CT of the chest with contrast is the most appropriate next step to characterize the lesion, assess for nodal involvement, and guide biopsy (D). Sputum AFB testing alone (A) would evaluate for tuberculosis but would miss the likely malignancy. Bronchoscopy (B) is useful for tissue diagnosis, but CT usually precedes it to localize the lesion and plan the approach. Empiric antibiotics (C) would delay the diagnosis of a probable malignancy. Repeating the chest X-ray in 6 weeks (E) is inappropriate when a mass is already visible and cancer is suspected.', 'Medium', 110, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 28-year-old man with cystic fibrosis presents with recurrent episodes of hemoptysis. CT of the chest shows diffuse bronchiectasis without any mass or cavity. He has no fever, and sputum cultures grow Pseudomonas aeruginosa. Which of the following is the most likely source of his hemoptysis?', '["Pulmonary embolism", "Hypertrophied bronchial arteries", "Mitral stenosis", "Goodpasture syndrome", "Active tuberculosis"]'::jsonb, 1, 'In cystic fibrosis with chronic bronchiectasis, the bronchial arteries hypertrophy and become tortuous to supply the chronically inflamed airways, and rupture of these high-pressure systemic vessels is the most common source of hemoptysis (B). Pulmonary embolism (A) typically causes pleuritic chest pain and dyspnea rather than recurrent hemoptysis in this setting. Mitral stenosis (C) can cause hemoptysis from pulmonary venous hypertension but is not suggested by the history or imaging. Goodpasture syndrome (D) causes alveolar hemorrhage with renal failure and would not present with isolated bronchiectasis. Active tuberculosis (E) is unlikely without cavitary lesions or systemic symptoms.', 'Medium', 111, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 62-year-old man with a 30 pack-year smoking history is found to have a 2.2 cm spiculated pulmonary nodule in the right upper lobe without calcification. PET-CT shows the nodule is FDG-avid. He has no prior imaging for comparison. Which of the following is the most appropriate next step?', '["Repeat CT in 12 months", "Sputum cytology", "CT-guided transthoracic needle biopsy", "Bronchoscopy with bronchoalveolar lavage only", "Start empiric antibiotics"]'::jsonb, 2, 'A large, spiculated, PET-avid nodule in a heavy smoker has a high pretest probability of malignancy, and tissue diagnosis is needed - CT-guided transthoracic needle biopsy is the most appropriate next step for a peripheral lesion (C). Surveillance imaging (A) is inappropriate for a high-risk nodule of this size and appearance. Sputum cytology (B) has low sensitivity for peripheral lesions. Bronchoscopy with lavage alone (D) has a low diagnostic yield for peripheral nodules and does not provide tissue for diagnosis. Antibiotics (E) would delay the diagnosis of a likely cancer.', 'Hard', 112, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 45-year-old nonsmoking woman undergoes CT of the abdomen for abdominal pain, and a 6 mm solid pulmonary nodule is incidentally noted in the right lower lobe. She has no history of cancer or prior lung disease. Which of the following is the most appropriate management according to the Fleischner Society guidelines?', '["CT surveillance in 6-12 months", "PET-CT", "Immediate tissue biopsy", "No follow-up imaging needed", "Surgical resection"]'::jsonb, 0, 'For a low-risk patient with a 6-8 mm solid nodule, the Fleischner guidelines recommend CT surveillance at 6-12 months, with consideration of a further scan at 18-24 months (A). PET-CT (B) is reserved for nodules 8 mm or larger with intermediate-to-high risk of malignancy. Immediate biopsy (C) is not indicated for a small nodule in a low-risk patient. Some follow-up is needed, so no imaging (D) is incorrect - nodules 6 mm or larger warrant surveillance. Surgical resection (E) is reserved for nodules with a high probability of malignancy or documented growth.', 'Medium', 113, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 70-year-old man is found to have a 1.5 cm pulmonary nodule with dense central calcification on chest CT. Review of prior imaging shows the nodule has been stable in size for 3 years. He is asymptomatic. Which of the following is the most appropriate management?', '["PET-CT", "Tissue biopsy", "Repeat CT in 3 months", "Surgical lobectomy", "No further imaging"]'::jsonb, 4, 'Dense central calcification is a benign pattern typical of a healed granuloma, and a solid nodule that has been stable for 2 or more years is considered benign, so no further imaging is needed (E). PET-CT (A) is unnecessary for a lesion with benign imaging features. Biopsy (B) carries procedural risk without benefit for a clearly benign nodule. Short-interval repeat CT (C) is not indicated when stability over 3 years has already been documented. Lobectomy (D) would be inappropriate surgery for a benign, asymptomatic lesion.', 'Easy', 114, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 68-year-old man with known heart failure presents with acute severe dyspnea, orthopnea, and pink frothy sputum. His blood pressure is 180/110 mmHg, heart rate 118/min, and oxygen saturation 86% on room air. Examination shows bilateral crackles, and chest X-ray shows bilateral perihilar infiltrates with an enlarged cardiac silhouette. Which of the following is the most appropriate initial treatment?', '["Intravenous antibiotics", "Intravenous furosemide", "High-dose inhaled bronchodilator", "Intravenous methylprednisolone", "Chest tube placement"]'::jsonb, 1, 'This is acute cardiogenic pulmonary edema from decompensated heart failure with volume overload, and intravenous loop diuretics such as furosemide are the mainstay of initial treatment to reduce preload and clear alveolar fluid (B). Antibiotics (A) are not indicated without evidence of infection. Inhaled bronchodilators (C) may help if there is bronchospasm but do not treat pulmonary edema. Corticosteroids (D) have no role in cardiogenic edema. A chest tube (E) is indicated for pneumothorax or large pleural effusion, not for diffuse pulmonary edema.', 'Medium', 115, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 30-year-old man is brought to the emergency department 6 hours after a near-drowning episode in fresh water. He is dyspneic with oxygen saturation 88% on room air. Chest X-ray shows diffuse bilateral infiltrates. BNP is 45 pg/mL, echocardiography shows a normal ejection fraction, and pulmonary capillary wedge pressure is 8 mmHg. Which of the following is the most likely diagnosis?', '["Cardiogenic pulmonary edema", "Pulmonary embolism", "Pneumothorax", "Noncardiogenic pulmonary edema (ARDS)", "Lobar pneumonia"]'::jsonb, 3, 'Diffuse bilateral infiltrates with a normal BNP, normal ejection fraction, and a low wedge pressure indicate permeability (noncardiogenic) pulmonary edema - in this case ARDS following aspiration of fresh water, which injures the alveolar-capillary membrane (D). Cardiogenic edema (A) would show an elevated BNP, reduced ejection fraction, and elevated wedge pressure. Pulmonary embolism (B) typically presents with pleuritic pain and a clear chest X-ray rather than diffuse infiltrates. Pneumothorax (C) would show absent breath sounds and a visible pleural line. Lobar pneumonia (E) causes a focal consolidation, not diffuse bilateral infiltrates.', 'Hard', 116, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 24-year-old woman presents to the emergency department with acute anxiety, rapid breathing, perioral tingling, and carpopedal spasm. Her respiratory rate is 30/min. Arterial blood gas shows pH 7.52, PaCO2 24 mmHg, and HCO3 22 mEq/L. She has no history of lung disease. Which of the following is the most appropriate management?', '["Reassurance with slow, controlled breathing", "Rebreathing into a paper bag", "Intravenous lorazepam immediately", "Supplemental oxygen at 15 L/min", "Intravenous calcium gluconate"]'::jsonb, 0, 'This is an acute respiratory alkalosis from hyperventilation due to anxiety, with the classic symptoms of perioral tingling and carpopedal spasm from reduced ionized calcium. Reassurance with slow, controlled breathing corrects the hypocapnia and resolves symptoms (A). Paper-bag rebreathing (B) is no longer recommended because it can cause hypoxia and is dangerous if an underlying cardiopulmonary cause is missed. Sedation with lorazepam (C) is not first-line and may mask another diagnosis. Supplemental oxygen (D) is unnecessary since oxygenation is normal. Calcium gluconate (E) treats true hypocalcemia, but the calcium here is functionally low due to alkalosis, not a true deficiency.', 'Easy', 117, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 66-year-old man with severe COPD presents with worsening dyspnea. He is alert and conversant. Arterial blood gas shows pH 7.34, PaCO2 62 mmHg, PaO2 58 mmHg, and HCO3 34 mEq/L. His oxygen saturation is 88% on 2 L of oxygen. Which of the following is the most appropriate management?', '["Emergent endotracheal intubation", "Intravenous sodium bicarbonate", "Controlled oxygen targeting SpO2 88-92% with bronchodilators", "High-flow oxygen targeting SpO2 100%", "Acetazolamide"]'::jsonb, 2, 'This is a chronic compensated respiratory acidosis - the elevated bicarbonate with a near-normal pH reflects renal compensation over days - so there is no acute emergency requiring intubation (C). Controlled oxygen targeting SpO2 88-92% with bronchodilators treats the COPD exacerbation while avoiding worsening hypercapnia. Emergent intubation (A) is not indicated in an alert patient with compensated hypercapnia. Sodium bicarbonate (B) is not used for chronic respiratory acidosis and can worsen CO2 retention. High-flow oxygen to 100% saturation (D) suppresses hypoxic drive and worsens hypercapnia in COPD. Acetazolamide (E) is not a treatment for respiratory acidosis.', 'Medium', 118, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 3-year-old boy suddenly begins choking and coughing while eating peanuts. The choking subsides, but he has a persistent cough and a localized wheeze over the right side of his chest. Chest X-ray shows hyperinflation of the right lung with a mediastinal shift to the left. Which of the following is the most appropriate next step?', '["CT of the chest", "Inhaled bronchodilators", "Flexible bronchoscopy alone", "Observation with repeat chest X-ray", "Rigid bronchoscopy for foreign body removal"]'::jsonb, 4, 'The history of choking while eating peanuts with persistent localized wheeze and unilateral hyperinflation is classic for foreign body aspiration, most commonly into the right main bronchus. Rigid bronchoscopy is the standard for both diagnosis and removal in children because it provides a secure airway and allows extraction of the object (E). CT of the chest (A) delays definitive treatment. Bronchodilators (B) do not address a mechanical obstruction. Flexible bronchoscopy (C) can diagnose the problem but is less suitable for removal in a young child. Observation (D) risks progression to atelectasis, pneumonia, or complete airway obstruction.', 'Medium', 119, 'MCQ'),
('af51c4aa-78d7-4cf9-b68d-bc661e6af9c0', 'A 78-year-old man with dysphagia after a recent stroke presents with his third episode of right lower lobe pneumonia in 6 months. He reports coughing and choking during meals. Chest X-ray shows a right lower lobe infiltrate. Which of the following is the most appropriate next step?', '["CT-guided lung biopsy", "Videofluoroscopic swallow study with dietary modification", "Long-term suppressive antibiotics", "Surgical lobectomy", "Bronchoscopy with biopsy"]'::jsonb, 1, 'Recurrent right lower lobe pneumonia with coughing during meals after a stroke strongly suggests chronic aspiration from dysphagia - the right lower lobe is the most dependent segment in an upright patient. A videofluoroscopic swallow study identifies the swallowing dysfunction and guides dietary modifications and swallowing therapy to prevent further aspiration (B). Lung biopsy (A) is not indicated for recurrent pneumonia with a clear clinical cause. Long-term antibiotics (C) treat the infection but not the underlying aspiration. Lobectomy (D) is inappropriate for an aspiration-related pneumonia. Bronchoscopy with biopsy (E) is not needed when the cause is clinically evident.', 'Medium', 120, 'MCQ');
